// the site timeline (from the Mukhtasar), in order: [title, the book's words, page, place in the timeline]
export const SI=[["مولده صلى الله عليه وسلم بمكة عام الفيل", "ولا خلاف أنه صلى الله عليه وسلم ولد بمكة عام الفيل.", 51, 0], ["قصة الفيل: بناء أبرهة كنيسة بصنعاء", "وكان سبب قصة الفيل - على ما ذكر محمد بن إسحاق - أن أبرهة بن الصباح كان عاملا للنجاشي ملك الحبشة على اليمن، فرأى الناس يتجهزون أيام الموسم إلى مكة - شرفها الله - فبنى كنيسة بصنعاء.", 51, 1], ["مسير أبرهة إلى مكة لهدم الكعبة", "فحلف أبرهة ليسيرن إلى الكعبة حتى يهدمها. وكتب إلى النجاشي يخبره بذلك، فسأله أن يبعث إليه بفيله.", 52, 2], ["قتال ذي نفر أبرهة وأسره", "فخرج ملك من ملوك اليمن، يقال له: ذو نفر. فقاتله. فهزمه أبرهة وأخذه أسيرا", 52, 3], ["قتال نفيل بن حبيب الخثعمي أبرهة وأسره", "فسار حتى إذا دنا من بلاد خثعم خرج إليه نفيل بن حبيب الخثعمي، ومن اجتمع إليه من قبائل العرب. فقاتلوهم فهزمهم أبرهة. فأخذ نفيلا", 52, 4], ["ثقيف تبعث أبا رغال دليلا وموته بالمغمس", "فبعثوا معه بأبي رغال مولى لهم. فخرج حتى إذا كان بالمغمس مات أبو رغال، وهو الذي يرجم قبره.", 52, 5], ["غارة الأسود بن مفصود على أموال الحرم", "فجمع الأسود إليه أموال الحرم، وأصاب لعبد المطلب مائتي بعير.", 52, 6], ["لقاء عبد المطلب أبرهة", "وكان عبد المطلب رجلا جسيما وسيما. فلما رآه أبرهة أعظمه وأكرمه.", 53, 7], ["رد الإبل على عبد المطلب وتحرز قريش في الشعاب", "ثم خرج وأخبر قريشا الخبر، وأمرهم أن يتفرقوا في الشعاب، ويتحرزوا في رؤوس الجبال، خوفا عليهم من معرة الجيش.", 54, 8], ["بروك الفيل وإرسال الطير على جيش أبرهة", "فأرسل الله طيرا من قبل البحر مع كل طائر ثلاثة أحجار. حجرين في رجليه وحجرا في منقاره. فلما غشيت القوم أرسلتها عليهم. فلم تصب تلك الحجارة أحدا إلا هلك.", 54, 9], ["هلاك أبرهة", "وبعث الله على أبرهة داء في جسده. فجعلت تساقط أنامله حتى انتهى إلى صنعاء وهو مثل الفرخ. وما مات حتى انصدع صدره عن قلبه ثم هلك.", 55, 10], ["وفاة عبد الله والد رسول الله ﷺ", "قد اختلف في وفاة أبيه: هل توفي بعد ولادته أو قبلها؛ الأكثر: على أنه توفي وهو حمل.", 55, 11], ["وفاة أمه بالأبواء", "ولا خلاف أن أمه ماتت بين مكة والمدينة بالأبواء، منصرفها من المدينة من زيارة أخواله. ولم يستكمل إذ ذاك ست سنين.", 55, 12], ["كفالة جده عبد المطلب له", "فكفله جده عبد المطلب. ورق عليه رقة لم يرقها على أولاده.", 55, 13], ["قول القافة من بني مدلج فيه", "وقدم مكة قوم من بني مدلج من القافة. فلما نظروا إليه قالوا لجده: احتفظ به.", 55, 14], ["وفاة جده عبد المطلب ووصيته به إلى أبي طالب", "وتوفي جده في السنة الثامنة من مولده. وأوصى به إلى أبي طالب.", 55, 15], ["استشهاد عبد الله بن الزبير بن عبد المطلب بأجنادين", "وأسلم من أولاده: عبد الله، واستشهد بأجنادين، وضباعة، ومجل، وصفية، وعاتكة.", 56, 16], ["موت أبي لهب عقيب بدر", "ومنهم: أبو لهب مات عقيب بدر.", 56, 17], ["دعاء النبي ﷺ على عتيبة بن أبي لهب وقتل السبع له", "وله من الولد: عتيبة الذي دعا عليه النبي صلى الله عليه وسلم فقتله السبع.", 56, 18], ["إسلام عتبة ومعتب ابني أبي لهب يوم الفتح", "وله عتبة، ومعتب. أسلما يوم الفتح.", 56, 19], ["منام عاتكة بنت عبد المطلب قبل بدر", "ومنهن: عاتكة أم عبد الله بن أبي أمية. وهي صاحبة المنام قبل يوم بدر.", 57, 20], ["موت هاشم بغزة وولادة عبد المطلب", "تزوجها أبوه هاشم بن عبد مناف. فخرج إلى الشام - وهي عند أهلها، قد حملت بعبد المطلب - فمات بغزة.", 57, 21], ["قدوم المطلب بشيبة (عبد المطلب) إلى مكة", "فقدم به مكة، فقال الناس: هذا عبد المطلب. فقال: ويحكم إنما هو ابن أخي هاشم.", 57, 22], ["تسليم المطلب ملك هاشم إلى عبد المطلب", "فأقام عنده حتى ترعرع. فسلم إليه ملك هاشم: من أمر البيت، والرفادة، والسقاية، وأمر الحجيج، وغير ذلك.", 58, 23], ["عقد المطلب الحلف بين قريش والنجاشي", "وهو الذي عقد الحلف بين قريش وبين النجاشي.", 58, 24], ["غصب نوفل أركاح شيبة بعد موت المطلب", "ولما مات وثب نوفل بن عبد مناف على أركاح شيبة. فغصبه إياها، فسأل رجالا من قريش النصرة على عمه.", 58, 25], ["نصرة أبي سعد بن عدي لعبد المطلب ورد أركاحه", "وسار من المدينة في ثمانين راكبا، حتى قدم مكة.", 59, 26], ["تحالف نوفل وبني عبد شمس، وبني هاشم وخزاعة", "فلما جرى ذلك حالف نوفل بني عبد شمس بن عبد مناف على بني هاشم، وحالفت بنو هاشم: خزاعة على بني عبد شمس ونوفل. فكان ذلك سببا لفتح مكة.", 59, 27], ["تحالف خزاعة في دار الندوة", "فدخلوا دار الندوة وتحالفوا وكتبوا بينهم كتابا.", 59, 28], ["غلبة خزاعة جرهما ونفيها من مكة", "فوقع بينهم وبين خزاعة حرب، وخزاعة من قبائل اليمن، من أهل سبأ. ولم يدخل بينهم بنو إسماعيل. فغلبتهم خزاعة. ونفت جرهما من مكة.", 60, 29], ["ظهور قصي بن كلاب على مكة", "وظهر بعد ذلك قصي بن كلاب على مكة. ورجع إليه ميراث قريش.", 60, 30], ["حفر عبد المطلب زمزم", "فبقيت زمزم مدفونة إلى عصر عبد المطلب. فرأى في المنام موضعها. فقام يحفر. فوجد فيها سيوفا مدفونة وحليا، وغزالا من ذهب مشنفا بالدر.", 60, 31], ["نذر عبد المطلب وفداء عبد الله بمائة من الإبل", "فخرج القدح على عبد الله. وأخذ عبد المطلب المدية ليذبحه. فقامت إليه قريش من ناديها فمنعوه.", 60, 32], ["جريان الدية مائة من الإبل", "فجرت الدية في قريش والعرب مائة من الإبل.. وأقرها رسول الله صلى الله عليه وسلم.", 61, 33], ["كفالة أبي طالب لرسول الله ﷺ", "قال الواقدي: قام أبو طالب - من سنة ثمان من مولد رسول الله صلى الله عليه وسلم إلى السنة العاشرة من النبوة ثلاثا وأربعين - يحوطه ويقوم بأمره، ويذب عنه.", 61, 34], ["وفاة أبي طالب على ملة عبد المطلب", "حتى كان آخر كلمة قالها: \"هو على ملة عبد المطلب \" فقال رسول الله صلى الله عليه وسلم: لأستغفرن لك ما لم أنه عنك", 62, 35], ["خروج طالب بن أبي طالب يوم بدر وفقده", "فأما طالب: فأخرجه المشركون يوم بدر كرها. فلما انهزم الكفار طلب، فلم يوجد في القتلى، ولا في الأسرى، ولا رجع إلى مكة، وليس له عقب.", 63, 36], ["أسر عقيل يوم بدر وفداء العباس له", "وأما عقيل: فأسر ذلك اليوم. ولم يكن له مال. ففداه عمه العباس.", 63, 37], ["هجرة عقيل إلى المدينة وشهوده مؤتة", "ثم رجع إلى مكة. فأقام بها إلى السنة الثامنة. ثم هاجر إلى المدينة. فشهد مؤتة مع أخيه جعفر.", 63, 38], ["خروجه مع أبي طالب إلى الشام ولقاء بحيرى", "فلما بلغ اثنتي عشرة سنة - وقيل: تسعا خرج به أبو طالب إلى الشام", 63, 39], ["خروجه إلى الشام في تجارة لخديجة", "فلما بلغ رسول الله صلى الله عليه وسلم خمسا وعشرين سنة: خرج إلى الشام في تجارة لخديجة رضي الله عنها، ومعه ميسرة غلامها. فوصل بصرى.", 64, 40], ["زواجه خديجة بنت خويلد", "ثم رجع فتزوج عقب رجوعه خديجة بنت خويلد. وهي أول امرأة تزوجها، وأول امرأة ماتت من نسائه.", 64, 41], ["تحنثه في غار حراء", "ثم حبب إليه الخلاء، والتعبد لربه، فكان يخلو بغار حراء يتعبد فيه وبغضت إليه الأوثان ودين قومه.", 64, 42], ["بناء قريش الكعبة", "ولما بلغ رسول الله صلى الله عليه وسلم خمسا وثلاثين سنة: قامت قريش في بناء الكعبة حين تضعضعت.", 65, 43], ["سرقة كنز الكعبة", "وذلك أن قوما سرقوا كنز الكعبة. وكان في بئر في جوف الكعبة.", 65, 44], ["تحطم سفينة الرومي بجدة وأخذ خشبها لسقف الكعبة", "رمى سفينة إلى جدة لرجل من تجار الروم، فتحطمت. فأخذوا خشبها فأعدوه لسقفها.", 66, 45], ["اختطاف الطائر حية الكعبة", "فبينما هي ذات يوم تتشرق على جدار الكعبة، بعث الله إليها طائرا فاختطفها. فذهب بها.", 66, 46], ["وثوب الحجر من يد أبي وهب المخزومي", "قام أبو وهب بن عمرو بن عائد المخزومي فتناول من الكعبة حجرا. فوثب من يده حتى رجع إلى موضعه", 66, 47], ["بدء الوليد بن المغيرة هدم الكعبة", "فقال الوليد بن المغيرة: أنا أبدؤكم في هدمها، فأخذ المعول.", 66, 48], ["انتهاء الهدم إلى أساس إبراهيم", "فلما تحرك الحجر: انتفضت مكة بأسرها. فانتهوا عند ذلك الأساس.", 67, 49], ["اختصام قريش في الحجر الأسود ولعقة الدم", "فسموا \" لعقة الدم\" فمكثت قريش على ذلك أربع ليال، أو خمسا.", 67, 50], ["تحكيم رسول الله ﷺ ووضعه الحجر الأسود", "فكان أول من دخل: رسول الله صلى الله عليه وسلم. فلما رأوه، قالوا: هذا الأمين، رضينا به، هذا محمد \"", 67, 51], ["نقله الحجارة وستر عورته", "وكان رسول الله صلى الله عليه وسلم ينقل معهم الحجارة.", 68, 52], ["تسقيف الكعبة وإخراج الحجر ورفع بابها", "فلما بلغوا خمسة عشر ذراعا سقفوه على ستة أعمدة.", 68, 53], ["كسوة الحجاج الكعبة الديباج", "وأول من كساه الديباج: الحجاج بن يوسف.", 68, 54], ["البعثة على رأس أربعين سنة", "فلما بلغ صلى الله عليه وسلم أربعين سنة: بعثه الله بشيرا ونذيرا. وداعيا إلى الله بإذنه وسراجا منيرا.", 68, 55], ["اختلاف الناس بعد آدم وبعث نوح", "ذكر لنا: أنه كان بين آدم ونوح عشرة قرون. كلهم على الهدى، وعلى شريعة من الحق. ثم اختلفوا بعد ذلك.", 68, 56], ["تصوير قوم نوح صالحيهم ثم عبادتهم", "ثم جاء القرن الثالث، فقالوا: ما عظم أولونا هؤلاء إلا وهم يرجون شفاعتهم عند الله، فعبدوهم.", 69, 57], ["إهباط الطوفان الأصنام إلى أرض جدة", "فلما بعث الله إليهم نوحا - وغرق من غرق - أهبط الماء هذه الأصنام من أرض إلى أرض، حتى قذفها إلى أرض جدة.", 69, 58], ["عمرو بن لحي يورد الأصنام تهامة", "فأتى جدة فاستثارها، ثم حملها حتى أوردها تهامة.", 69, 59], ["دعوة عمرو بن لحي العرب إلى عبادة الأصنام وتوزيعها", "وحضر الحج، فدعا العرب إلى عبادتها. فأجابه عوف بن عذرة، فدفع إليه ودا فحمله.", 70, 60], ["هدم خالد بن الوليد ودا", "فبعث رسول الله صلى الله عليه وسلم خالد بن الوليد لهدمه. فحالت بينه وبينه بنو عذرة وبنو عامر، فقاتلهم فقتلهم. ثم هدمه وجعله جذاذا.", 70, 61], ["هدم علي مناة عام الفتح", "فبعث رسول الله صلى الله عليه وسلم عليا رضي الله عنه فهدمها عام الفتح.", 71, 62], ["اتخاذ اللات في الطائف", "ثم اتخذوا اللات في الطائف، قيل: إن أصل ذلك رجل كان يلت السويق للحاج، فمات. فعكفوا على قبره.", 71, 63], ["هدم المغيرة بن شعبة اللات", "فلما أسلمت ثقيف، بعث رسول الله صلى الله عليه وسلم المغيرة بن شعبة فهدمها، وحرقها بالنار.", 72, 64], ["عضد خالد بن الوليد العزى", "فلما فتح رسول الله صلى الله عليه وسلم مكة، بعث خالد بن الوليد فأتاها فعضدها، وكانت ثلاث سمرات.", 72, 65], ["قول أبي سفيان يوم أحد: اعل هبل", "وهو الذي قال فيه أبو سفيان يوم أحد: \" اعل هبل \"", 72, 66], ["مسخ إساف ونائلة حجرين", "فدخلا البيت، ففجر بها فيه. فمسخهما الله فيه حجرين", 73, 67], ["هدم جرير بن عبد الله ذا الخلصة", "فسار إليه بأحمس. فقاتلته همدان، فظفر بهم وهدمه.", 73, 68], ["تكسير الأصنام حول البيت يوم الفتح", "ولما فتح رسول الله صلى الله عليه وسلم وجد حول البيت ثلاثمائة وستين صنما.", 74, 69], ["بدء الوحي ونزول اقرأ في غار حراء", "حتى فاجأه الحق، وهو في غار حراء، فجاءه الملك. فقال: اقرأ، فقلت: ما أنا بقارئ.", 74, 70], ["ذهاب خديجة به إلى ورقة بن نوفل", "فانطلقت به خديجة حتى أتت به ورقة بن نوفل بن أسد بن عبد العزى - ابن عم خديجة -", 75, 71], ["وفاة ورقة وفترة الوحي", "فلم يلبث ورقة أن توفي، وفتر الوحي.", 76, 72], ["نزول يا أيها المدثر وتتابع الوحي", "فأنزل الله ﴿يا أيها المدثر - قم فأنذر﴾ [المدثر: 1 - 2] فحمي الوحي وتتابع.", 76, 73], ["إسلام أبي بكر ومن استجاب له", "فكان حائز السبق: صديق الأمة أبا بكر رضي الله عنه. فوازره في دين الله. ودعا معه إلى الله. فاستجاب لأبي بكر عثمان وطلحة وسعد رضي الله عنهم.", 78, 74], ["إسلام خديجة وعلي بن أبي طالب", "وبادر إلى استجابته أيضا صديقة النساء خديجة رضي الله عنها. وبادر إلى الإسلام علي بن أبي طالب رضي الله عنه. وكان ابن ثمان سنين، وقيل: أكثر.", 78, 75], ["إسلام زيد بن حارثة", "وبادر زيد بن حارثة رضي الله عنه، حب رسول الله صلى الله عليه وسلم، وكان غلاما لخديجة، فوهبته لرسول الله صلى الله عليه وسلم لما تزوجها.", 78, 76], ["قدوم حارثة وأخيه في فداء زيد", "وقدم أبوه حارثة وعمه في فدائه", 78, 77], ["تبني رسول الله ﷺ زيدا ثم نزول ادعوهم لآبائهم", "أشهدكم أن زيدا ابني، أرثه ويرثني فلما رأى ذلك أبوه وعمه طابت نفوسهما. فانصرفا. ودعي: زيد بن محمد، حتى جاء الله بالإسلام فنزلت: ﴿ادعوهم لآبائهم هو أقسط عند الله﴾", 79, 78], ["إسلام ورقة بن نوفل", "وأسلم ورقة بن نوفل.", 79, 79], ["عيبه دين قريش وابتداء عداوتهم", "وقريش لا تنكر ذلك، حتى بادأهم بعيب دينهم وسب آلهتهم وأنها لا تضر ولا تنفع.", 79, 80], ["تعذيب آل ياسر", "منهم: عمار بن ياسر، وأمه سمية، وأهل بيته. عذبوا في الله.", 80, 81], ["مقتل سمية أول شهيدة", "ومر أبو جهل بسمية - أم عمار رضي الله عنهما - وهي تعذب، وزوجها وابنها. فطعنها بحربة في فرجها فقتلها.", 80, 82], ["عتق أبي بكر بلالا وغيره من المعذبين", "وكان الصديق إذا مر بأحد من العبيد يعذب اشتراه وأعتقه. منهم بلال.", 80, 83], ["تعذيب قريش من آمن من عشائرهم", "لما ظهر الإسلام، أتى جماعة من كفار قريش إلى من آمن من عشائرهم، فعذبوهم وسجنوهم، وأرادوا أن يفتنوهم عن دينهم.", 80, 84], ["الدعوة سرا ثلاث سنين ثم إعلانها في الرابعة", "قام رسول الله صلى الله عليه وسلم بمكة ثلاث سنين مستخفيا. ثم أعلن في الرابعة.", 81, 85], ["عرضه نفسه على القبائل في المواسم", "فدعا الناس عشر سنين، يوافي المواسم كل عام، يتبع الناس في منازلهم. وفي المواسم بعكاظ، ومجنة، وذي المجاز", 81, 86], ["صعوده الصفا ونزول تبت يدا أبي لهب", "ولما نزل عليه قوله تعالى: ﴿وأنذر عشيرتك الأقربين﴾ [الشعراء: 214] صعد الصفا فنادى: واصباحاه.", 81, 87], ["نزول فاصدع بما تؤمر", "دعا رسول الله صلى الله عليه وسلم إلى الله مستخفيا ثلاث سنين، ثم نزل عليه: ﴿فاصدع بما تؤمر وأعرض عن المشركين﴾", 81, 88], ["أول دم أهريق في الإسلام", "وفي السنة الرابعة: ضرب سعد بن أبي وقاص رجلا من المشركين فشجه.", 82, 89], ["استهزاء المشركين بالمستضعفين", "فإذا مرت بهم قريش استهزءوا بهم، وقالوا: أهؤلاء - جلساؤه - قد من الله عليهم من بيننا؟ فأنزل الله: ﴿أليس الله بأعلم بالشاكرين﴾", 82, 90], ["نهي أبي جهل النبي ﷺ عن الصلاة", "فبلغه أن رسول الله يصلي، فأتاه. فقال: ألم أنهك عن الصلاة؟ فانتهره رسول الله صلى الله عليه وسلم.", 82, 91], ["الهجرة الأولى إلى الحبشة", "وفي السنة الخامسة: أمر النبي صلى الله عليه وسلم أصحابه بالهجرة إلى الحبشة لما اشتد عليهم العذاب والأذى.", 83, 92], ["رجوع مهاجرة الحبشة إلى مكة", "وكان خروجهم في رجب. فأقاموا بالحبشة شعبان ورمضان. ثم رجعوا إلى مكة في شوال", 84, 93], ["قراءته سورة النجم وسجود المشركين", "فلما بلغ السجدة سجد، وسجد معه المسلمون والمشركون كلهم.", 84, 94], ["اشتداد قريش على من أسلم", "ولما استمر النبي صلى الله عليه وسلم على سب آلهتهم، عادوا إلى شر مما كانوا عليه، وازدادوا شدة على من أسلم.", 84, 95], ["الهجرة الثانية إلى الحبشة", "فأذن لهم رسول الله صلى الله عليه وسلم في الخروج إلى الحبشة مرة ثانية. فخرجوا.", 85, 96], ["رجوع بعض مهاجرة الحبشة لما سمعوا بالهجرة", "فلما سمعوا بمهاجر رسول الله صلى الله عليه وسلم إلى المدينة، رجع منهم ثلاثة وثلاثون رجلا، ومن النساء ثمان.", 85, 97], ["كتاب رسول الله ﷺ إلى النجاشي", "فلما كان شهر ربيع سنة سبع من الهجرة. كتب رسول الله صلى الله عليه وسلم كتابا إلى النجاشي يدعوه إلى الإسلام.", 85, 98], ["تنصر عبد الله بن جحش زوج أم حبيبة وموته نصرانيا", "وكانت مهاجرة مع زوجها عبد الله بن جحش. فتنصر هناك ومات نصرانيا.", 85, 99], ["إسلام النجاشي وتزويجه أم حبيبة", "فلما قرأ الكتاب أسلم. وقال: لو قدرت أن آتيه لأتيته. وزوجه أم حبيبة، وأصدقها عنه أربعمائة دينار.", 85, 100], ["قدوم أصحاب الحبشة على رسول الله ﷺ بخيبر", "وحمل بقية أصحابه في سفينتين. فقدموا على رسول الله صلى الله عليه وسلم بخيبر، وقد فتحها.", 85, 101], ["بعث قريش إلى النجاشي تطلب إرجاع المسلمين", "ولما كان بعد بدر: اجتمعت قريش في دار الندوة. وقالوا: إن لنا في الذين عند النجاشي ثأرا.", 86, 102], ["دخول جعفر والمسلمين على النجاشي ومحاورته", "فدعاهم النجاشي. فلما حضروا صاح جعفر بن أبي طالب بالباب \"يستأذن عليك حزب الله\"", 86, 103], ["قراءة جعفر القرآن على النجاشي ونزول آية المائدة", "فقال: اقرأ مما يقرأ عليكم. فقرأ سورتي العنكبوت والروم. ففاضت عينا النجاشي من الدمع.", 88, 104], ["تأمين النجاشي للمسلمين بأرضه", "فأقبل النجاشي على جعفر. ثم قال: اذهبوا فأنتم سيوم بأرضي - والسيوم الآمنون - من سبكم غرم.", 89, 105], ["موت النجاشي وصلاة النبي ﷺ عليه", "ولما مات النجاشي، خرج رسول الله صلى الله عليه وسلم فصلى عليه كما يصلي على الجنائز.", 89, 106], ["استتاره ﷺ في دار الأرقم", "وفي سنة خمس من النبوة استتر رسول الله صلى الله عليه وسلم في دار الأرقم بن أبي الأرقم.", 89, 107], ["إسلام حمزة بن عبد المطلب", "وفي السنة السادسة، أسلم حمزة بن عبد المطلب وعمر.", 89, 108], ["إسلام عمر رضي الله عنه", "لم سميت الفاروق؟ فقال: أسلم حمزة قبلي بثلاثة أيام. ثم شرح الله صدري للإسلام.", 90, 109], ["خروج المسلمين في صفين إلى المسجد وتسمية عمر الفاروق", "فخرجنا في صفين. حمزة في صف، وأنا في صف - له كديد ككديد الطحن - حتى دخلنا المسجد.", 91, 110], ["مشي قريش إلى أبي طالب بعمارة بن الوليد", "ولما رأت قريش أن رسول الله صلى الله عليه وسلم يتزايد أمره ويقوى، ورأوا ما صنع أبو طالب به. مشوا إليه بعمارة بن الوليد.", 91, 111], ["كلام أبي طالب لابن أخيه وجوابه ﷺ", "فبعث أبو طالب إلى رسول الله صلى الله عليه وسلم، فقال له: يا ابن أخي، إن قومك جاءوني، وقالوا كذا وكذا، فأبق علي وعلى نفسك، ولا تحملني ما لا أطيق أنا ولا أنت.", 92, 112], ["إجابة بني هاشم وبني المطلب أبا طالب إلى نصرته", "ودعا أبو طالب أقاربه إلى نصرته فأجابه بنو هاشم وبنو المطلب، غير أبي لهب، وقال أبو طالب:", 92, 113], ["كتابة قريش الصحيفة على بني هاشم", "وكتبوا بذلك صحيفة فيها عهود ومواثيق \" ألا يقبلوا من بني هاشم", 92, 114], ["حصار بني هاشم في شعب أبي طالب", "فأمرهم أبو طالب أن يدخلوا شعبه فلبثوا فيه ثلاث سنين. واشتد عليهم البلاء وقطعوا عنهم الأسواق.", 93, 115], ["تعاقد النفر على نقض الصحيفة", "فاجتمعوا عند الحجون، وتعاقدوا على القيام بنقض الصحيفة. فقال زهير أنا أبدأ بها.", 96, 116], ["أكل الأرضة الصحيفة وإخبار أبي طالب قريشا", "وبعث الله على صحيفتهم الأرضة فلم تترك اسما لله إلا لحسته وبقي ما فيها من شرك وظلم وقطيعة", 97, 117], ["فتح الصحيفة فوجدوها كما أخبر", "قالوا: قد رضينا. ففتحوا الصحيفة فوجدوها كما أخبر.", 98, 118], ["إسلام هشام بن عمرو", "وأسلم هشام بن عمرو يوم الفتح.", 98, 119], ["خروج بني هاشم من الشعب", "وخرج بنو هاشم من شعبهم وخالطوا الناس. وكان خروجهم في سنة عشر من النبوة.", 98, 120], ["موت أبي طالب", "ومات أبو طالب بعدها بستة أشهر.", 98, 121], ["موت خديجة أم المؤمنين", "وماتت خديجة أم المؤمنين -رضي الله عنها- بعد موت أبي طالب بأيام.", 98, 122], ["اجتماع أشراف قريش في الحجر وغمزهم له ﷺ", "حضرتهم. وقد اجتمع أشرافهم في الحجر. فذكروا رسول الله -صلى الله عليه وسلم -.", 98, 123], ["وثوب قريش عليه ﷺ ودفاع أبي بكر عنه", "فلما كان من الغد اجتمعوا فقالوا: ذكرتم ما بلغ منكم حتى إذا أتاكم بما تكرهون تركتموه.", 99, 124], ["إلقاء سلا الجزور على ظهره وهو يصلي", "ومرة كان يصلي عند البيت، ورهط من أشرافهم يرونه فأتى أحدهم بسلا جزور. فرماه على ظهره.", 99, 125], ["استماع أبي جهل والأخنس قراءته ليلا", "وذكر الزهري: أن أبا جهل. وجماعة معه وفيهم الأخنس بن شريق، استمعوا قراءة رسول الله -صلى الله عليه وسلم - في الليل", 99, 126], ["بعث قريش النضر بن الحارث وعقبة إلى أحبار المدينة", "بعثت قريش النضر بن الحارث وعقبة بن أبي معيط، إلى أحبار بالمدينة", 100, 127], ["نزول سورة الكهف وآية الروح جوابا لسؤالهم", "فجاءه جبريل بسورة الكهف فيها خبر ما سألوه عنه. من الفتية والرجل الطواف.", 101, 128], ["سماع الوليد بن المغيرة القرآن", "إن الوليد بن المغيرة جاء إلى النبي -صلى الله عليه وسلم - فقال اقرأ علي.", 102, 129], ["اتفاق قريش في الموسم على قول: ساحر", "فتفرقوا عنه بذلك. فجعلوا يجلسون للناس لا يمر بهم أحد إلا حذروه رسول الله -صلى الله عليه وسلم -.", 103, 130], ["نزول آيات المدثر في الوليد بن المغيرة", "فأنزل الله في الوليد بن المغيرة ﴿ذرني ومن خلقت وحيدا﴾ [المدثر: 11]", 103, 131], ["نزول آية عضين في النفر الذين معه", "ونزل في النفر الذين كانوا معه يصنفون القول في رسول الله صلى الله عليه وسلم وفيما جاء به من عند الله ﴿الذين جعلوا القرآن عضين﴾ [الحجر: 91]", 104, 132], ["انشقاق القمر", "فمن ذلك أنهم سألوه أن يريهم آية فأراهم انشقاق القمر.", 104, 133], ["سؤال أهل مكة أن يجعل لهم الصفا ذهبا", "سأله أهل مكة أن يجعل لهم الصفا ذهبا وأن ينحي عنهم الجبال حتى يزرعوا.", 105, 134], ["افتراس الأسد من دعا عليه النبي ﷺ", "والذي دعا عليه النبي -صلى الله عليه وسلم - أن يسلط عليه كلبا من كلابه فافترسه الأسد", 108, 135], ["خروجه ﷺ إلى الطائف", "ولما اشتد البلاء من قريش على رسول الله -صلى الله عليه وسلم - بعد موت عمه خرج إلى الطائف، رجاء أن يؤوه وينصروه على قومه ويمنعوه منهم حتى يبلغ رسالة ربه.", 111, 136], ["إقامته بالطائف ورميه بالحجارة", "فأقام بينهم عشرة أيام. لا يدع أحدا من أشرافهم إلا كلمه فقالوا: اخرج من بلدنا.", 112, 137], ["دعاؤه ﷺ في مرجعه من الطائف", "وفي مرجعه دعا بالدعاء المشهور", 112, 138], ["إرسال ملك الجبال إليه", "فأرسل ربه تبارك وتعالى إليه ملك الجبال يستأمره أن يطبق الأخشبين على أهل مكة", 112, 139], ["استماع نفر من الجن قراءته بنخلة", "فلما نزل بنخلة في مرجعه قام يصلي من الليل ما شاء الله فصرف الله إليه نفرا من الجن.", 112, 140], ["دخوله مكة في جوار المطعم بن عدي", "فأرسل رجلا من خزاعة إلى المطعم بن عدي أدخل في جوارك؟ فقال نعم.", 113, 141], ["الإسراء والمعراج", "ثم أسري برسول الله -صلى الله عليه وسلم - إلى بيت المقدس راكبا على البراق صحبة جبريل عليه السلام. فنزل هناك. وصلى بالأنبياء إماما.", 113, 142], ["إعطاؤه الصلاة", "وكلمه ربه وأعطاه ما أعطاه. وأعطاه الصلاة.", 114, 143], ["إخباره قومه بالإسراء وتكذيبهم", "فلما أصبح رسول الله -صلى الله عليه وسلم - في قومه وأخبرهم اشتد تكذيبهم له وسألوه أن يصف لهم بيت المقدس.", 114, 144], ["عرضه ﷺ نفسه على الحاج في الموسم", "كان يوافي الموسم كل عام يتبع الحاج في منازلهم وفي عكاظ وغيرها. يدعوهم إلى الله.", 115, 145], ["بيعة العقبة الأولى: إسلام ستة نفر من الخزرج", "فلقي رسول الله -صلى الله عليه وسلم - في الموسم عند العقبة: ستة نفر من الأنصار كلهم من الخزرج.", 115, 146], ["قدوم اثني عشر رجلا من الأنصار في العام المقبل", "فلما كان العام المقبل جاء منهم اثنا عشر رجلا - الستة الأول. خلا جابرا - ومعهم عبادة بن الصامت، وأبو الهيثم بن التيهان، وغيرهم.", 116, 147], ["الحرب بين الأوس والخزرج", "فوقعت بينهم العداوة بسبب قتيل فلبثت بينهم الحرب مائة وعشرين سنة إلى أن أطفأها الله بالإسلام.", 116, 148], ["بعث مصعب بن عمير إلى المدينة", "فلما انصرفوا بعث معهم رسول الله -صلى الله عليه وسلم - مصعب بن عمير، وأمره أن يقرئهم القرآن ويعلمهم الإسلام.", 116, 149], ["إسلام أسيد بن حضير", "فقام واغتسل. وطهر ثوبه. وتشهد وصلى ركعتين.", 117, 150], ["إسلام سعد بن معاذ", "فعرض عليه الإسلام وقرأ عليه القرآن. قال فعرفنا والله في وجهه الإسلام قبل أن يتكلم في إشراقه وتهلله.", 118, 151], ["إسلام بني عبد الأشهل", "فما أمسى فيهم رجل ولا امرأة إلا أسلموا، إلا الأصيرم.", 119, 152], ["إسلام الأصيرم وقتله يوم أحد", "فإنه تأخر إسلامه إلى يوم أحد. فأسلم وقاتل وقتل ولم يسجد لله سجدة.", 119, 153], ["انتشار الإسلام في دور الأنصار", "فأقام مصعب في منزل أسعد يدعو الناس إلى الإسلام حتى لم يبق دار من دور الأنصار إلا وفيها رجال ونساء مسلمون", 119, 154], ["تأخر إسلام بعض دور الأنصار حتى عام الخندق", "وذلك أنهم كان فيهم قيس بن الأسلت الشاعر. وكانوا يسمعون منه فوقف بهم عن الإسلام حتى كان عام الخندق، بعد أن هاجر رسول الله -صلى الله عليه وسلم -.", 119, 155], ["خروج من أسلم من الأنصار حجاجا", "فلما كان من العام المقبل. وجاء موسم الحج. قال من أسلم من الأنصار: حتى متى نترك رسول الله -صلى الله عليه وسلم - يطرد في جبال مكة ويخاف؟ ! فخرجوا مع مشركي قومهم حجاجا.", 119, 156], ["بيعة العقبة الثانية", "فلما وصلوا واعدوه العقبة، من أواسط أيام التشريق للبيعة بعد ما انقضى حجهم.", 119, 157], ["إسلام عبد الله بن عمرو بن حرام أبي جابر", "فأخبروه الخبر فأسلم وشهد العقبة وكان نقيبا.", 120, 158], ["اجتماع الأنصار به ﷺ ليلا وكلام العباس", "فلما مضى ثلث الليل خرجوا للميعاد حتى اجتمعوا عنده من رجل ورجلين ومعه عمه العباس - وهو يومئذ على دين قومه -", 120, 159], ["مبايعة الأنصار وأولهم البراء بن معرور", "فكان أول من بايعه البراء بن معرور. فقال والذي بعثك بالحق لنمنعك مما نمنع منه أزرنا.", 121, 160], ["اختيار اثني عشر نقيبا", "ثم قال رسول الله -صلى الله عليه وسلم - «أخرجوا إلي منكم اثني عشر نقيبا كفلاء على قومهم ككفالة الحواريين لعيسى ابن مريم وأنا كفيل على قومي»", 121, 161], ["صراخ الشيطان بعد بيعة العقبة", "فلما بايعوه صرخ الشيطان بأنفذ صوت سمع قط يا أهل الأخاشب هل لكم في محمد والصبأة معه؟ قد اجتمعوا على حربكم.", 122, 162], ["غدو جلة قريش على الأنصار", "فلما أصبحوا غدت عليهم جلة قريش. فقالوا: إنه بلغنا أنكم جئتم صاحبنا البارحة تستخرجونه من بين أظهرنا، وتبايعونه على حربنا.", 122, 163], ["أسر قريش سعد بن عبادة", "فلما انفصلت الأنصار عن مكة: صح الخبر عند قريش. فخرجوا في طلبهم فأدركوا سعد بن عبادة، والمنذر بن عمرو. فأعجزهم المنذر ومضى.", 123, 164], ["هاتف على أبي قبيس بالسعدين", "وسمعت قريش قائلا يقول بالليل على أبي قبيس:", 124, 165], ["الإذن للمسلمين بالهجرة إلى المدينة", "وأذن رسول الله -صلى الله عليه وسلم - للمسلمين في الهجرة إلى المدينة. فبادروا إليها. وأول من خرج أبو سلمة بن عبد الأسد وزوجته أم سلمة.", 125, 166], ["تآمر قريش بدار الندوة", "فاجتمعوا في دار الندوة. وحضرهم إبليس في صورة شيخ من أهل نجد.", 125, 167], ["إذن الله لرسوله في الخروج وصحبة أبي بكر", "فقال رسول الله -صلى الله عليه وسلم -: \" إن الله قد أذن لي في الخروج \" فقال أبو بكر: الصحبة يا رسول الله. قال: \" نعم \"", 126, 168], ["مبيت علي على الفراش وخروج النبي ﷺ عليهم", "وأمر عليا أن يبيت تلك الليلة على فراشه.", 126, 169], ["خروج رسول الله ﷺ وأبي بكر إلى غار ثور", "ومضى رسول الله -صلى الله عليه وسلم - إلى بيت أبي بكر. فخرجا من خوخة في بيت أبي بكر ليلا.", 127, 170], ["وصول قريش إلى باب الغار", "وجدت قريش في طلبهما، وأخذوا معهم القافة حتى انتهوا إلى باب الغار. فوقفوا عليه.", 127, 171], ["تلقيب أسماء ذات النطاقين", "فقطعت أسماء بنت أبي بكر. قطعة من نطاقها، فأوكت به فم الجراب وقطعت الأخرى عصاما للقربة. فبذلك لقبت \" ذات النطاقين \".", 128, 172], ["الارتحال من الغار بعد ثلاث", "ومكثا في الغار ثلاثا. حتى خمدت نار الطلب. فجاءهما ابن أريقط بالراحلتين فارتحلا، وأردف أبو بكر عامر بن فهيرة.", 128, 173], ["قصة سراقة بن مالك", "ففطن بالأمر سراقة بن مالك، فأراد أن يكون الظفر له.", 128, 174], ["قصة أم معبد", "ثم مروا بخيمة أم معبد الخزاعية، وكانت امرأة برزة جلدة تحتبي بفناء الخيمة ثم تطعم وتسقي من مر بها،", 129, 175], ["صوت بمكة بخبر خيمة أم معبد", "وأصبح صوت عال بمكة يسمعونه ولا يرون القائل يقول:", 130, 176], ["أبو قحافة وأسماء ومال أبي بكر", "قالت ولما خرج أبو بكر احتمل معه ماله. فدخل علينا جدي أبو قحافة - وقد ذهب بصره -", 132, 177], ["دخول رسول الله ﷺ المدينة", "فلما كان يوم الاثنين ثاني عشر ربيع الأول على رأس ثلاث عشرة سنة من نبوته. خرجوا على عادتهم.", 132, 178], ["نزوله بقباء في بني عمرو بن عوف", "فلما أتى المدينة، عدل ذات اليمين حتى نزل بقباء في بني عمرو بن عوف، ونزل على كلثوم بن الهدم - أو على سعد بن خيثمة -", 132, 179], ["تأسيس مسجد قباء", "وأسس مسجد قباء. وهو أول مسجد أسس بعد النبوة.", 133, 180], ["الجمعة في بني سالم بن عوف", "فلما كان يوم الجمعة ركب. فأدركته الجمعة في بني سالم بن عوف. فجمع بهم في المسجد الذي في بطن الوادي.", 133, 181], ["بروك الناقة ونزوله على أبي أيوب", "وبادر أبو أيوب خالد بن زيد إلى رحله فأدخله بيته.", 133, 182], ["نزول «وقل رب أدخلني مدخل صدق»", "قال ابن عباس: كان النبي -صلى الله عليه وسلم - بمكة فأمر بالهجرة.", 134, 183], ["أول من قدم المدينة من المهاجرين", "قال البراء.: أول من قدم علينا: مصعب بن عمير، وابن أم مكتوم، فجعلا يقرءان الناس القرآن.", 135, 184], ["قدوم بنات رسول الله ﷺ وأهله من مكة", "وبعث رسول الله -صلى الله عليه وسلم - وهو في منزل أبي أيوب - زيد بن حارثة وأبا رافع. وأعطاهما بعيرين وخمسمائة درهم إلى مكة، فقدما عليه بفاطمة وأم كلثوم ابنتيه.", 135, 185], ["بناء المسجد النبوي", "فساوم رسول الله -صلى الله عليه وسلم - الغلامين بالمربد ليتخذه مسجدا فقالا: بل نهبه لك يا رسول الله. فأبى رسول الله صلى الله عليه وسلم فاشتراه منهما بعشرة دنانير.", 136, 186], ["بناؤه بعائشة", "وكان بناؤه بها في شوال من السنة الأولى،", 137, 187], ["المؤاخاة بين المهاجرين والأنصار", "ثم آخى بين المهاجرين والأنصار، وكانوا تسعين رجلا. نصفهم من المهاجرين، ونصفهم من الأنصار،", 137, 188], ["رد التوارث إلى الأرحام", "فلما أنزل الله ﴿وأولو الأرحام بعضهم أولى ببعض في كتاب الله﴾ [الأنفال: 75] رد التوارث إلى الأرحام.", 137, 189], ["وباء المدينة ومرض أبي بكر وبلال", "قدم رسول الله -صلى الله عليه وسلم - المدينة وهي وبيئة. فمرض أبو بكر.", 137, 190], ["زيادة ركعتين في صلاة الحضر", "وفي السنة الأولى: زيد في صلاة الحضر ركعتين. فصارت أربع ركعات.", 138, 192], ["نزول أهل الصفة المسجد", "وفيها: نزل أهل الصفة المسجد.", 138, 193], ["وفيات: أسعد بن زرارة والبراء وضمرة وكلثوم", "وتوفي البراء بن معرور في صفر قبل قدوم رسول الله -صلى الله عليه وسلم - المدينة. وهو أول من مات من النقباء.", 139, 194], ["موادعة يهود المدينة", "وفيها: وادع رسول الله -صلى الله عليه وسلم - من بالمدينة من اليهود. وكتب بينه وبينهم كتابا.", 139, 195], ["إسلام عبد الله بن سلام", "وبادر عالم اليهود وحبرهم عبد الله بن سلام فأسلم.", 139, 196], ["نقض اليهود العهد ومحاربتهم", "فنقض الثلاث العهد. وحاربهم. فمن على بني قينقاع وأجلى بني النضير. وقتل بني قريظة.", 139, 197], ["رؤيا الأذان", "وفي السنة الثانية رأى عبد الله بن زيد بن عبد ربه الأذان فأمره رسول الله -صلى الله عليه وسلم - أن يلقيه على بلال.", 140, 199], ["فرض صوم رمضان", "وفيها: فرض صوم رمضان. ونسخ صوم عاشوراء. وبقي صومه مستحبا.", 140, 200], ["تزويج علي فاطمة", "وفيها: زوج رسول الله -صلى الله عليه وسلم - عليا فاطمة رضي الله عنهما.", 140, 201], ["تحويل القبلة إلى الكعبة", "وفيها: صرف الله عز وجل القبلة عن بيت المقدس إلى الكعبة.", 140, 202], ["الإذن في القتال ثم فرضه", "فحينئذ أذن لهم في القتال ولم يفرضه عليهم فقال تعالى ﴿أذن للذين يقاتلون بأنهم ظلموا وإن الله على نصرهم لقدير﴾ [الحج: 39] وهي أول آية نزلت في القتال.", 143, 203], ["أول لواء: لواء حمزة", "وأول لواء عقده رسول الله -صلى الله عليه وسلم - على قول موسى بن عقبة - لواء حمزة بن عبد المطلب في شهر رمضان في السنة الأولى،", 145, 204], ["سرية عبيدة بن الحارث", "ثم بعث عبيدة بن الحارث بن عبد المطلب بن عبد مناف في شوال من تلك السنة في سرية إلى بطن رابغ في ستين رجلا من المهاجرين خاصة.", 145, 205], ["سرية سعد بن أبي وقاص إلى الخرار", "ثم بعث سعد بن أبي وقاص في ذي القعدة من تلك السنة إلى الخرار من أرض الحجاز، يعترضون عيرا لقريش.", 145, 206], ["غزوة الأبواء", "فغزا فيها -صلى الله عليه وسلم - غزوة الأبواء. وكانت أول غزوة غزاها رسول الله -صلى الله عليه وسلم - بنفسه.", 146, 207], ["موادعة بني ضمرة", "وفيها وادع بني ضمرة على أن لا يغزوهم ولا يغزوه ولا يعينوا عليه أحدا.", 146, 208], ["غزوة بواط", "ثم غزا بواطا في ربيع الأول. خرج يعترض عيرا لقريش فيها أمية بن خلف ومائة رجل من المشركين.", 146, 209], ["الخروج في طلب كرز بن جابر", "ثم خرج في طلب كرز بن جابر الفهري. وقد أغار على سرح المدينة، فاستاقه.", 146, 210], ["غزوة العشيرة", "ثم خرج في جمادى الآخرة في مائة وخمسين من المهاجرين يعترضون عيرا لقريش ذاهبة إلى الشام.", 146, 211], ["موادعة بني مدلج", "وفيها: وادع بني مدلج وحلفاءهم.", 147, 212], ["بعث عبد الله بن جحش إلى نخلة", "ثم بعث عبد الله بن جحش إلى نخلة في رجب في اثني عشر رجلا من المهاجرين كل اثنين على بعير.", 147, 213], ["قتل عمرو بن الحضرمي", "فمرت بهم عير قريش تحمل زبيبا وتجارة فيها عمرو بن الحضرمي، فقتلوه وأسروا عثمان ونوفلا ابني عبد الله بن المغيرة والحكم بن كيسان مولى بني المغيرة.", 147, 214], ["أول خمس وأول قتل وأول أسر ونزول آية الشهر الحرام", "ثم قدموا بالعير والأسيرين حتى عزلوا من ذلك الخمس. فكان أول خمس في الإسلام وأول قتل في الإسلام وأول أسر. فأنكر رسول الله -صلى الله عليه وسلم - ما فعلوه.", 148, 215], ["وقعة بدر الكبرى", "فلما كان في رمضان بلغ رسول الله -صلى الله عليه وسلم - خبر العير المقبلة من الشام مع أبي سفيان فيها أموال قريش فندب رسول الله -صلى الله عليه وسلم - للخروج إليها فخرج مسرعا في ثلاثمائة وبضع عشرة رجلا.", 149, 216], ["استصراخ أبي سفيان قريشا ونفيرهم", "وبلغ أبا سفيان مخرج رسول الله -صلى الله عليه وسلم -. فاستأجر ضمضم بن عمرو الغفاري.", 149, 217], ["استشارة الأصحاب قبل بدر", "ولما بلغ رسول الله صلى الله عليه وسلم خروج قريش استشار أصحابه.", 150, 218], ["نجاة العير وإصرار أبي جهل", "وخفض أبو سفيان. فلحق بساحل البحر. وكتب إلى قريش أن ارجعوا فإنكم إنما خرجتم لتحرزوا عيركم.", 151, 219], ["رجوع الأخنس وبني زهرة وطالب بن أبي طالب", "فأشار الأخنس بن شريق عليهم بالرجوع فلم يفعلوا. فرجع هو وبنو زهرة.", 151, 220], ["النزول على أدنى مياه بدر ونزول المطر", "وسار رسول الله -صلى الله عليه وسلم - حتى نزل على ماء أدنى مياه بدر.", 151, 221], ["إشارة النبي ﷺ إلى مصارع القوم", "ومشى رسول الله -صلى الله عليه وسلم - في موضع المعركة. وجعل يشير بيده ويقول: «هذا مصرع فلان وهذا مصرع فلان إن شاء الله.»", 152, 222], ["استنصار النبي ﷺ ربه وإمداد الملائكة", "وقام ورفع يديه واستنصر ربه وبالغ في التضرع ورفع يديه حتى سقط رداؤه.", 152, 223], ["نشوب الحرب يوم بدر", "وأمر أبو جهل عامر بن الحضرمي - أخا عمرو بن الحضرمي - أن يطلب دم أخيه. فصاح. وكشف عن استه يصرخ واعمراه واعمراه. فحمي القوم. ونشبت الحرب.", 153, 224], ["هزيمة المشركين يوم بدر", "ومنح الله المسلمين أكتاف المشركين. فتناولوهم قتلا وأسرا. فقتلوا سبعين وأسروا سبعين.", 153, 225], ["المبارزة يوم بدر", "وخرج عتبة وشيبة ابنا ربيعة والوليد بن عتبة: يطلبون المبارزة.", 153, 226], ["وفاة عبيدة بن الحارث بالصفراء", "ومات بالصفراء وفيهم نزلت ﴿هذان خصمان اختصموا في ربهم﴾ [الحج: 19]- الآية", 154, 227], ["تبدي إبليس لقريش في صورة سراقة", "فتبدى لهم إبليس في صورة سراقة بن مالك.", 154, 228], ["استشهاد عمير بن الحمام أول قتيل", "فرمى بهن وقاتل حتى قتل فكان أول قتيل.", 155, 229], ["رمي النبي ﷺ التراب في وجوه القوم", "وأخذ رسول الله -صلى الله عليه وسلم - ملء كفه ترابا فرمى به في وجوه القوم.", 155, 230], ["مقتل أبي جهل", "فانطلق ابن مسعود فوجده قد ضربه معوذ وعوف - ابنا عفراء - حتى برد.", 155, 231], ["مقتل أبي جهل", "قال له هل أخزاك الله يا عدو الله؟ قال وهل فوق رجل قتله قومه؟ فاحتز رأسه عبد الله بن مسعود.", 156, 232], ["مقتل أمية بن خلف", "وأسر عبد الرحمن بن عوف أمية بن خلف وابنه عليا. فأبصره بلال - وكان يعذبه بمكة - فقال رأس الكفر أمية؟ لا نجوت إن نجا.", 156, 233], ["انقطاع سيف عكاشة بن محصن", "وانقطع يومئذ سيف عكاشة بن محصن. فأعطاه النبي -صلى الله عليه وسلم - جذلا من حطب فلما أخذه وهزه عاد في يده سيفا طويلا", 156, 234], ["وقوف النبي ﷺ على قتلى بدر", "ولما انقضت الحرب أقبل النبي -صلى الله عليه وسلم - حتى وقف على القتلى.", 156, 235], ["إلقاء القتلى في قليب بدر", "ثم أمر بهم فسحبوا حتى ألقوا في القليب - قليب بدر -", 157, 236], ["قتل النضر بن الحارث وعقبة بن أبي معيط", "فلما كان بالصفراء قسم الغنائم وضرب عنق النضر بن الحارث. ثم لما نزل بعرق الظبية ضرب عنق عقبة بن أبي معيط.", 157, 237], ["دخول المدينة بعد بدر وإسلام كثير من أهلها", "فأسلم بشر كثير من أهل المدينة ودخل عبد الله بن أبي رأس المنافقين وأصحابه في الإسلام.", 157, 238], ["عدد من حضر بدرا ومن استشهد", "وجملة من حضر بدرا: ثلاثمائة وبضع عشرة رجلا. واستشهد منهم أربعة عشر رجلا.", 157, 239], ["نزول آية في المفتونين الذين خرجوا إلى بدر", "ثم ساروا مع قومهم إلى بدر. فأصيبوا فأنزل الله فيهم ﴿إن الذين توفاهم الملائكة ظالمي أنفسهم﴾ [النساء: 97]", 157, 240], ["قسم غنائم بدر", "ثم إن رسول الله -صلى الله عليه وسلم - أمر بالغنائم فجمعت فاختلفوا.", 157, 241], ["تفريق أسرى بدر والوصية بهم", "فرق رسول الله -صلى الله عليه وسلم - الأسرى على أصحابه. وقال استوصوا بالأسرى خيرا", 158, 242], ["أسارى بدر والاستشارة فيهم", "واستشار رسول الله -صلى الله عليه وسلم - أصحابه في الأسرى وهم سبعون. وكذلك القتلى سبعون أيضا.", 158, 243], ["نزول آية ما كان لنبي أن يكون له أسرى", "فلا ينفلتن منهم أحد إلا بفداء أو ضرب عنق. فأنزل الله تعالى ﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض﴾ [الأنفال: 67]", 159, 244], ["فداء العباس", "وقال الأنصار للنبي -صلى الله عليه وسلم - نريد أن نترك لابن أختنا العباس فداءه فقال «لا تدعوا منه درهما»", 159, 245], ["غزوة بني قينقاع", "فكانت فيها غزوة بني قينقاع وكانوا من يهود المدينة. فنقضوا العهد. فحاصرهم رسول الله -صلى الله عليه وسلم - خمس عشرة ليلة.", 160, 247], ["غزوة أحد", "وفيها كانت وقعة أحد في شوال.", 160, 248], ["استشارة الصحابة في الخروج إلى أحد", "فاستشار رسول الله -صلى الله عليه وسلم - أصحابه في الخروج إليهم. وكان رأيه أن لا يخرجوا.", 160, 249], ["الخروج إلى أحد في ألف", "فخرج في ألف من أصحابه واستعمل على المدينة عبد الله بن أم مكتوم.", 161, 250], ["رؤيا النبي ﷺ قبل أحد", "وكان رسول الله -صلى الله عليه وسلم - رأى رؤيا: رأى أن في سيفه ثلمة وأن بقرا تذبح. وأنه يدخل يده في درع حصينة.", 161, 251], ["انخزال عبد الله بن أبي بثلث العسكر", "فلما كان بالشوط - بين المدينة وأحد - انخزل عبد الله بن أبي بنحو ثلث العسكر", 161, 252], ["مرور الجيش بحائط مربع بن قيظي", "فخرج به بعض الأنصار، حتى سلك في حائط لمربع بن قيظي من المنافقين - وكان أعمى - فقام يحثو التراب في وجوه المسلمين", 161, 253], ["نزول الشعب من أحد وتعبئة المسلمين", "فلما أصبح يوم السبت تعبأ للقتال. وهو في سبعمائة منهم خمسون فارسا.", 162, 254], ["رد من استصغر عن القتال", "واستعرض الشباب يومئذ. فرد من استصغر عن القتال - كابن عمر وأسامة بن زيد والبراء وزيد بن أرقم وزيد بن ثابت، وعرابة الأوسي - وأجاز من رآه مطيقا.", 162, 255], ["تعبئة قريش يوم أحد", "وتعبأت قريش وهم ثلاثة آلاف وفيهم مائتا فارس فجعلوا على ميمنتهم خالد بن الوليد. وعلى الميسرة عكرمة بن أبي جهل.", 162, 256], ["قتال أبي عامر الفاسق المسلمين", "وكان أول من بدر من المشركين أبو عامر - عبد عمرو بن صيفي - الفاسق.", 162, 257], ["انهزام المشركين أول النهار ثم إخلاء الرماة الثغر", "فلما رأى ذلك الرماة قالوا: الغنيمة الغنيمة. فذكرهم أميرهم عهد رسول الله -صلى الله عليه وسلم - فلم يسمعوا. فأخلوا الثغر وكر فرسان المشركين عليه فوجدوه خاليا.", 163, 258], ["جرح النبي ﷺ وكسر رباعيته ومقتل مصعب بن عمير", "وخلص المشركون إلى رسول الله -صلى الله عليه وسلم - فجرحوه جراحات وكسروا رباعيته. وقتل مصعب بن عمير بين يديه. فدفع اللواء إلى علي بن أبي طالب.", 163, 259], ["رد عين قتادة بن النعمان", "وأصيبت يومئذ عين قتادة بن النعمان. فأتى بها رسول الله -صلى الله عليه وسلم - فردها بيده. فكانت أحسن عينيه.", 163, 260], ["صراخ الشيطان بقتل النبي ﷺ واستشهاد أنس بن النضر", "وصرخ الشيطان إن محمدا قد قتل فوقع ذلك في قلوب كثير من المسلمين", 163, 261], ["مقتل حمزة بن عبد المطلب", "وقتل وحشي الحبشي حمزة بن عبد المطلب -رضي الله عنه-. رماه بحربة على طريقة الحبشة.", 164, 262], ["اجتماع المسلمين إلى النبي ﷺ في الشعب", "فكان أول من عرفه تحت المغفر كعب بن مالك.", 164, 263], ["مقتل أبي بن خلف", "فلما اقترب منه طعنه رسول الله -صلى الله عليه وسلم - في ترقوته فكر منهزما.", 164, 264], ["صلاة النبي ﷺ بهم جالسا يوم أحد", "وحانت الصلاة فصلى بهم رسول الله -صلى الله عليه وسلم - جالسا.", 164, 265], ["استشهاد حنظلة بن أبي عامر", "وشد حنظلة بن أبي عامر على أبي سفيان. فلما تمكن منه حمل عليه شداد بن الأسود فقتله وكان حنظلة جنبا.", 164, 266], ["إسلام الأصيرم واستشهاده", "فلما كان يوم أحد قذف الله الإسلام في قلبه للحسنى التي سبقت له. فأسلم وأخذ سيفه.", 165, 267], ["نداء أبي سفيان بعد انقضاء الحرب", "ولما انقضت الحرب أشرف أبو سفيان على الجبل ونادى: أفيكم محمد؟", 165, 268], ["قتال الملائكة يوم أحد", "وقاتلت الملائكة يوم أحد عن رسول الله -صلى الله عليه وسلم -.", 165, 269], ["نزول آية وما محمد إلا رسول", "فقال الأنصاري إن كان قد قتل فقد بلغ فقاتلوا عن دينكم فنزل ﴿وما محمد إلا رسول قد خلت من قبله الرسل﴾ [آل عمران: 144]", 166, 270], ["ما نزل من القرآن في يوم أحد", "فكان مما نزل من القرآن في يوم أحد إحدى وستون آية من آل عمران", 166, 271], ["المسير إلى حمراء الأسد", "فبلغ ذلك رسول الله -صلى الله عليه وسلم -. فنادى في الناس بالمسير إليهم وقال لا يخرج معنا إلا من شهد القتال", 166, 272], ["وقعة خبيب وأصحابه", "ثم دخلت السنة الرابعة. فكانت فيها وقعة خبيب وأصحابه في صفر.", 167, 274], ["وقعة بئر معونة", "وفي هذا الشهر بعينه من السنة المذكورة كانت وقعة أهل بئر معونة.", 167, 275], ["غزوة بني النضير", "وفي شهر ربيع الأول كانت غزوة بني النضير. ونزل فيها سورة الحشر.", 167, 276], ["غزوة المريسيع على بني المصطلق", "فكانت فيها غزوة المريسيع على بني المصطلق فأغار عليهم رسول الله -صلى الله عليه وسلم - وهم غارون.", 167, 278], ["زواج النبي ﷺ من جويرية بنت الحارث", "وكان من جملة السبي جويرية بنت الحارث، سيد القوم وقعت في سهم ثابت بن قيس فكاتبها، فأدى عنها رسول الله -صلى الله عليه وسلم - وتزوجها", 168, 279], ["قصة الإفك", "وفي هذه الغزوة كانت قصة الإفك.", 168, 280], ["احتباس الوحي شهرا في شأن عائشة", "واقتضى تمام الابتلاء أن حبس الله عن رسوله الوحي شهرا في شأنها", 169, 281], ["نزول براءة عائشة", "قالت فنزل الوحي على رسول الله -صلى الله عليه وسلم -.", 169, 282], ["اعتذار حسان إلى عائشة", "وكان حسان -رضي الله عنه- ممن قيل عنه إنه يتكلم مع أهل الإفك فقال يعتذر إلى عائشة. ويمدحها:", 170, 283], ["نزول أول سورة النور في قصة الإفك", "فأنزل الله تعالى في هذه القصة أول سورة النور", 171, 284], ["غزوة الأحزاب (الخندق)", "وفي هذه السنة - وهي سنة خمس - كانت وقعة الخندق في شوال.", 171, 285], ["حفر الخندق بمشورة سلمان الفارسي", "فأشار عليه سلمان الفارسي بحفر خندق يحول بين العدو وبين المدينة.", 171, 286], ["خروج المسلمين في ثلاثة آلاف وتحصنهم", "وخرج رسول الله -صلى الله عليه وسلم - في ثلاثة آلاف من المسلمين. فتحصن بالجبل من خلفه - جبل سلع - وبالخندق أمامه.", 172, 287], ["نقض بني قريظة العهد", "فلم يزل به حتى نقض العهد الذي بينه وبين رسول الله -صلى الله عليه وسلم - ودخل مع المشركين.", 172, 288], ["بعث السعدين إلى بني قريظة", "فبعث إليهم السعدين - سعد بن معاذ، وسعد بن عبادة - وخوات بن جبير. وعبد الله بن رواحة ليتعرفوا الخبر", 172, 289], ["استئذان بعض بني حارثة في الذهاب إلى المدينة", "واستأذن بعض بني حارثة رسول الله -صلى الله عليه وسلم - في الذهاب إلى المدينة.", 173, 290], ["حصار المشركين شهرا ومقتل عمرو بن عبد ود", "وأقام المشركون محاصرين رسول الله -صلى الله عليه وسلم - شهرا.", 173, 291], ["مفاوضة غطفان على ثلث ثمار المدينة", "أراد رسول الله -صلى الله عليه وسلم - أن يصالح عيينة بن حصن والحارث بن عوف - رئيسي غطفان - على ثلث ثمار المدينة وينصرفا بقومهما.", 173, 292], ["إسلام نعيم بن مسعود وتخذيله الأحزاب", "فمن ذلك أن رجلا من غطفان - يقال له نعيم بن مسعود - جاء إلى رسول الله -صلى الله عليه وسلم -. فقال قد أسلمت، فمرني بما شئت.", 174, 293], ["تخاذل قريش وبني قريظة", "فلما جاءتهم رسلهم قالوا: قد صدقكم والله نعيم. فبعثوا إليهم إنا والله لا نبعث إليكم أحدا. فقالت قريظة قد صدقكم والله نعيم. فتخاذل الفريقان.", 174, 294], ["إرسال الريح على المشركين ورحيلهم", "وأرسل الله على المشركين جندا من الريح فجعلت تقوض خيامهم", 175, 295], ["غزوة بني قريظة", "فجاءه جبريل وقت الظهر فقال أقد وضعتم السلاح؟ إن الملائكة لم تضع أسلحتها، انهض إلى هؤلاء - يعني بني قريظة -", 175, 296], ["حكم سعد بن معاذ في بني قريظة", "فحكم فيهم سعد بن معاذ فحكم أن تقتل الرجال وتقسم الأموال وتسبى النساء والذراري", 176, 297], ["نزول صدر سورة الأحزاب", "وأنزل الله في غزوة الخندق صدر سورة الأحزاب", 176, 298], ["وقعة الحديبية", "وفيها كانت وقعة الحديبية. وعدة الصحابة إذ ذاك ألف وأربعمائة.", 176, 300], ["بروك القصواء ونزول أقصى الحديبية", "بركت راحلته فقال الناس حل حل. فقالوا: خلأت القصواء", 177, 301], ["جيشان الماء بالسهم في الحديبية", "فانتزع سهما من كنانته. وأمرهم أن يجعلوه فيه فوالله ما زال يجيش لهم بالري حتى صدروا عنه.", 177, 302], ["إرسال عثمان إلى قريش", "فدعاه فأرسله إلى قريش، وقال أخبرهم أنا لم نأت لقتال", 177, 303], ["معركة بين المسلمين والمشركين بالنبل والحجارة", "فرمى رجل من أحد الفريقين رجلا من الفريق الآخر. فكانت معركة. وتراموا بالنبل والحجارة.", 178, 304], ["بيعة الرضوان تحت الشجرة", "وبلغ رسول الله -صلى الله عليه وسلم - أن عثمان قد قتل. فدعا إلى البيعة. فتبادروا إليه وهو تحت الشجرة فبايعوه على أن لا يفروا.", 178, 305], ["رجوع عثمان من مكة", "ولما تمت البيعة رجع عثمان", 179, 306], ["مجيء بديل بن ورقاء", "فبينا هم كذلك إذ جاء بديل بن ورقاء في نفر خزاعة", 179, 307], ["مجيء عروة بن مسعود", "فقال عروة بن مسعود إن هذا قد عرض عليكم خطة رشد فاقبلوها ودعوني آته. فقالوا: ائته. فأتاه.", 180, 308], ["مجيء رجل من بني كنانة", "فقال رجل من بني كنانة دعوني آته فقالوا: ائته.", 181, 309], ["كتابة صلح الحديبية مع سهيل بن عمرو", "فبينا هم كذلك إذ جاء سهيل بن عمرو.", 181, 310], ["مجيء أبي جندل يرسف في قيوده وطلب سهيل رده", "فبينا هم كذلك إذ جاء أبو جندل بن سهيل وقد خرج من أسفل مكة يرسف في قيوده حتى رمى بنفسه بين أظهر المسلمين.", 182, 311], ["مراجعة عمر النبي ﷺ في الصلح", "قال عمر بن الخطاب: والله ما شككت منذ أسلمت إلا يومئذ.", 182, 312], ["النحر والحلق بالحديبية", "فلما فرغ من قضية الكتاب قال رسول الله -صلى الله عليه وسلم - لأصحابه قوموا فانحروا.", 182, 313], ["مجيء نسوة مؤمنات ونزول آية الامتحان", "ثم جاء نسوة مؤمنات فأنزل الله ﴿يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن﴾ [الممتحنة: 10]", 183, 314], ["طلاق عمر امرأتين كانتا له في الشرك", "فطلق عمر يومئذ امرأتين كانتا له في الشرك.", 183, 315], ["نزول سورة الفتح", "وفي مرجعه -صلى الله عليه وسلم - أنزل الله سورة الفتح", 183, 316], ["قصة أبي بصير", "ولما رجع إلى المدينة جاءه أبو بصير - رجل من قريش - مسلما، فأرسلوا في طلبه رجلين", 183, 317], ["لحاق أبي جندل بأبي بصير بسيف البحر", "فخرج حتى أتى سيف البحر. وتفلت منهم أبو جندل. فلحق بأبي بصير.", 184, 318], ["مناشدة قريش النبي ﷺ أن يرسل إليهم", "فأرسلت قريش إلى النبي -صلى الله عليه وسلم - تناشده الله والرحم لما أرسل إليهم فمن أتاه منهم فهو آمن.", 184, 319], ["غزوة خيبر", "ولما قدم رسول الله -صلى الله عليه وسلم - من الحديبية، مكث بالمدينة عشرين يوما، أو قريبا منها. ثم خرج إلى خيبر واستخلف على المدينة سباع بن عرفطة", 184, 320], ["قدوم أبي هريرة المدينة مسلما", "وقدم أبو هريرة حينئذ المدينة مسلما.", 184, 321], ["مبارزة مرحب ومقتل عامر بن الأكوع", "فاختلفا ضربتين. فوقع سيف مرحب في ترس عامر فعضه. فذهب عامر يسفل له - وكان سيفه قصيرا - فرجع إليه سيفه فأصاب ركبته فمات.", 185, 322], ["حصار خيبر قريبا من عشرين ليلة", "فحاصرهم رسول الله -صلى الله عليه وسلم - قريبا من عشرين ليلة.", 186, 323], ["استشهاد العبد الأسود", "قال نعم فتقدم. فقاتل حتى قتل", 186, 324], ["افتتاح خيبر وصلح أهلها", "فحاصرهم حتى إذا أيقنوا بالهلكة سألوه الصلح. ونزل إليه سلام بن أبي الحقيق فصالحهم على حقن الدماء", 186, 325], ["معاملة أهل خيبر على شطر الثمر وقسمها", "فأعطاهم إياها، على شطر ما يخرج من ثمرها وزرعها.", 187, 326], ["قدوم جعفر بن أبي طالب وصحبه من الحبشة", "وفي هذه الغزوة قدم عليه ابن عمه جعفر بن أبي طالب وأصحابه. ومعهم الأشعريون: أبو موسى، وأصحابه.", 187, 327], ["محاصرة يهود وادي القرى", "ثم انصرف رسول الله -صلى الله عليه وسلم - من خيبر إلى وادي القرى وكان به جماعة من اليهود، وانضاف إليهم جماعة من العرب.", 188, 328], ["مقتل مدعم عبد رسول الله ﷺ", "فقتل مدعم - عبد لرسول الله -صلى الله عليه وسلم -.", 188, 329], ["افتتاح وادي القرى عنوة", "فلم ترتفع الشمس قدر رمح حتى افتتحها عنوة.", 188, 330], ["رد المهاجرين منائح الأنصار", "ولما رجع إلى المدينة رد المهاجرون إلى الأنصار منائحهم من النخيل.", 189, 331], ["بعث سرية إلى الحرقات", "ثم بعث رسول الله -صلى الله عليه وسلم - سرية إلى الحرقات من جهينة.", 189, 332], ["عمرة القضية", "فلما كان في ذي القعدة من السنة السابعة خرج رسول الله -صلى الله عليه وسلم - معتمرا عمرة القضية.", 189, 333], ["زواج النبي ﷺ من ميمونة بنت الحارث", "وبعث جعفر بن أبي طالب بين يديه إلى ميمونة بنت الحارث يخطبها. فجعلت أمرها إلى العباس. فزوجه إياها.", 189, 334], ["طواف المسلمين ورملهم في عمرة القضية", "فلما قدم رسول الله -صلى الله عليه وسلم - أمر أصحابه أن يكشفوا عن المناكب ويسعوا في الطواف ليرى المشركون قوتهم", 190, 335], ["الإقامة بمكة ثلاثا والخروج منها", "فأقام بمكة ثلاثا. ثم أتاه سهيل بن عمرو، وحويطب بن عبد العزى.", 190, 336], ["غزوة مؤتة", "ثم دخلت السنة الثامنة فكانت فيها غزوة مؤتة", 190, 338], ["مقتل الحارث بن عمير رسول النبي ﷺ", "بعث الحارث بن عمير بكتاب إلى ملك الروم - أو بصرى - فعرض له شرحبيل بن عمرو الغساني. فقتله", 190, 339], ["بعث البعوث إلى مؤتة وتأمير زيد ثم جعفر ثم ابن رواحة", "فبعث البعوث. واستعمل عليهم زيد بن حارثة، وقال إن أصيب زيد فجعفر بن أبي طالب على الناس وإن أصيب جعفر فعبد الله بن رواحة فتجهزوا. وهم ثلاثة آلاف.", 191, 340], ["نزولهم معان وبلوغهم خبر هرقل", "ثم مضوا حتى نزلوا معان. فبلغهم أن هرقل بالبلقاء في مائة ألف من الروم وانضم إليه من لخم وجذام وبلي وغيرهم مائة ألف.", 191, 341], ["القتال عند مؤتة ومقتل زيد وجعفر", "فانحاز المسلمون إلى مؤتة. ثم اقتتلوا عندها والراية في يد زيد. فلم يزل يقاتل بها حتى شاط في رماح القوم.", 192, 342], ["مقتل عبد الله بن رواحة", "ثم أخذها عبد الله بن رواحة. فتقدم بها، وهو على فرسه فجعل يستنزل نفسه ويقول:", 192, 343], ["أخذ خالد بن الوليد الراية وانصراف الناس", "ثم أخذ الراية خالد بن الوليد. فدافع القوم وخاشى بهم ثم انحازوا، وانصرف الناس.", 193, 344], ["غزوة الفتح الأعظم", "وكانت سنة ثمان في رمضان.", 194, 345], ["عدوان بني بكر على خزاعة بالوتير", "ثم إن بني بكر وثبوا على خزاعة ليلا بماء، يقال له: الوتير، قريبا من مكة. وأعانت قريش بني بكر بالسلاح.", 194, 346], ["قدوم عمرو بن سالم الخزاعي المدينة مستنصرا", "فخرج عمرو بن سالم الخزاعي، حتى قدم على رسول الله صلى الله عليه وسلم المدينة.", 194, 347], ["قدوم بديل بن ورقاء في نفر من خزاعة", "ثم خرج بديل بن ورقاء في نفر من خزاعة، حتى قدموا على رسول الله صلى الله عليه وسلم المدينة، فأخبروه بما أصيب منهم، وبمظاهرة قريش بني بكر عليهم.", 195, 348], ["قدوم أبي سفيان المدينة", "ثم قدم أبو سفيان. فدخل على ابنته أم حبيبة.", 195, 349], ["إجارة أبي سفيان بين الناس ورجوعه إلى مكة", "فقام أبو سفيان في المسجد، فقال: يا أيها الناس، إني قد أجرت بين الناس. ثم ركب بعيره، وانصرف عائدا إلى مكة.", 196, 350], ["أمر النبي ﷺ الناس بالجهاز", "وأمر رسول الله صلى الله عليه وسلم الناس بالجهاز، وقال: «اللهم خذ العيون والأخبار عن قريش، حتى نبغتها في بلادها».", 196, 351], ["كتاب حاطب بن أبي بلتعة إلى قريش", "فكتب حاطب بن أبي بلتعة إلى قريش كتابا، يخبرهم فيه بمسير رسول الله صلى الله عليه وسلم.", 197, 352], ["مسير رسول الله ﷺ إلى مكة", "ثم مضى رسول الله صلى الله عليه وسلم، وعمى الله الأخبار عن قريش، لكنهم على وجل.", 197, 353], ["هجرة العباس ولقاؤه النبي ﷺ بالجحفة", "وكان العباس قد خرج قبل ذلك بأهله وعياله مسلما مهاجرا. فلقي رسول الله صلى الله عليه وسلم بالجحفة.", 198, 354], ["النزول بمر الظهران وإيقاد النيران", "فلما نزل رسول الله صلى الله عليه وسلم مر الظهران نزل العشاء، فأمر الجيش فأوقدوا النيران. فأوقد أكثر من عشرة آلاف نارا.", 198, 355], ["العباس يأتي بأبي سفيان ليستأمن له", "فاركب في عجز هذه البغلة، حتى آتيه بك، فأستأمنه لك. فركب خلفي. ورجع صاحباه. فجئت به.", 198, 356], ["إسلام أبي سفيان", "فقال له العباس: ويحك. أسلم قبل أن يضرب عنقك. قال: فشهد شهادة الحق، فأسلم.", 199, 357], ["الأمان لمن دخل دار أبي سفيان أو أغلق بابه أو دخل المسجد", "«نعم من دخل دار أبي سفيان فهو آمن، ومن أغلق عليه بابه فهو آمن ومن دخل المسجد فهو آمن».", 200, 358], ["مرور الكتائب بأبي سفيان ونزع اللواء من سعد بن عبادة", "وكانت راية الأنصار مع سعد بن عبادة، فلما مر بأبي سفيان، قال: اليوم يوم الملحمة.", 200, 359], ["أبو سفيان ينذر قريشا", "ومضى أبو سفيان. فلما جاء قريشا صرخ بأعلى صوته. هذا محمد قد جاءكم بما لا قبل لكم به، فمن دخل دار أبي سفيان فهو آمن.", 200, 360], ["دخول رسول الله ﷺ مكة من أعلاها", "وسار رسول الله صلى الله عليه وسلم حتى دخل مكة من أعلاها،", 200, 361], ["قتال الخندمة", "وتجمع سفهاء قريش مع عكرمة بن أبي جهل، وصفوان بن أمية، وسهيل بن عمرو، بالخندمة ليقاتلوا.", 201, 362], ["الطواف بالبيت وطعن الأصنام بالقوس وتساقطها", "ثم طاف بالبيت. وفي يده قوس، وحول البيت وعليه، ثلاثمائة وستون صنما. فجعل يطعنها بالقوس،", 202, 363], ["دخول الكعبة ومحو الصور", "فلما أكمله دعا عثمان بن طلحة، فأخذ منه مفتاح الكعبة. فأمر بها ففتحت. فدخلها.", 202, 364], ["خطبته على باب الكعبة: اذهبوا فأنتم الطلقاء", "ثم قال: «يا معشر قريش، ما ترون أني فاعل بكم؟ قالوا: خيرا، أخ كريم، وابن أخ كريم. قال: فإني أقول لكم كما قال يوسف لإخوته: لا تثريب عليكم اليوم، اذهبوا فأنتم الطلقاء».", 203, 365], ["رد مفتاح الكعبة إلى عثمان بن طلحة", "فقال: \" هاك مفتاحك يا عثمان، اليوم يوم بر ووفاء.", 203, 366], ["أذان بلال على الكعبة", "وأمر بلالا أن يصعد على الكعبة فيؤذن", 203, 367], ["إسلام الحارث بن هشام وعتاب بن أسيد", "فقال الحارث وعتاب: نشهد أنك رسول الله.", 204, 368], ["صلاة الفتح في دار أم هانئ", "ثم دخل صلى الله عليه وسلم دار أم هانئ فاغتسل. وصلى ثمان ركعات، صلاة الفتح.", 204, 369], ["أمان الناس إلا تسعة نفر", "ولما استقر الفتح: أمن رسول الله صلى الله عليه وسلم الناس كلهم، إلا تسعة نفر. فإنه أمر بقتلهم، وإن وجدوا تحت أستار الكعبة:", 204, 370], ["خطبة الغد من يوم الفتح في حرمة مكة", "فلما كان الغد من يوم الفتح: قام رسول الله صلى الله عليه وسلم في الناس خطيبا.", 205, 371], ["هم فضالة بن عمير بقتل النبي ﷺ وهو يطوف", "وهم فضالة بن عمير بن الملوح الليثي أن يقتل رسول الله صلى الله عليه وسلم، وهو يطوف.", 205, 372], ["فرار صفوان بن أمية وعكرمة ورجوعهما", "وفر يومئذ صفوان بن أمية، وعكرمة بن أبي جهل. فاستأمن عمير بن وهب رسول الله لصفوان، فلحقه. وهو يريد أن يركب البحر فرده.", 206, 373], ["تجديد أنصاب الحرم", "ثم أمر رسول الله صلى الله عليه وسلم عتاب بن أسيد الخزاعي فجدد أنصاب الحرم.", 206, 374], ["بعث السرايا إلى الأوثان حول مكة", "وبعث صلى الله عليه وسلم سراياه إلى الأوثان التي حول مكة فكسرت كلها، منها اللات والعزى ومناة.", 206, 375], ["هدم عمرو بن العاص صنم سواع", "وبعث عمرو بن العاص في شهر رمضان إلى سواع - وهو لهذيل -", 206, 376], ["بعث سعد بن زيد لهدم مناة", "ثم بعث سعد بن زيد بن مالك بن عبد بن كعب بن عبد الأشهل، الأشهلي الأنصاري، في شهر رمضان إلى مناة.", 206, 377], ["غزوة حنين", "قال ابن إسحاق: لما سمعت هوازن بالفتح، جمعها مالك بن عوف النصري مع هوازن ثقيف كلها.", 207, 378], ["نزول هوازن بأوطاس ومشورة دريد بن الصمة", "فلما أجمع مالك السير إلى رسول الله صلى الله عليه وسلم، ساق مع الناس أموالهم ونساءهم وذراريهم. فلما نزل بأوطاس، اجتمعوا إليه.", 207, 379], ["بعث عبد الله بن أبي حدرد عينا إلى هوازن", "ولما سمع بهم رسول الله صلى الله عليه وسلم بعث إليهم عبد الله بن أبي حدرد الأسلمي. وأمره أن يداخلهم حتى يعلم علمهم.", 209, 380], ["استعارة أدراع صفوان بن أمية", "فأعطاه مائة درع بما يكفيها السلاح.", 209, 381], ["خروج النبي ﷺ إلى حنين في اثني عشر ألفا", "فخرج صلى الله عليه وسلم. ومعه ألفان من أهل مكة، وعشرة آلاف من أصحابه الذين فتح الله بهم مكة. فكانوا اثني عشر ألفا. واستعمل عتاب بن أسيد على مكة.", 209, 382], ["انهزام الناس أول الأمر بوادي حنين", "فوالله ما راعنا إلا الكتائب، قد شدوا علينا شدة رجل واحد، فانشمر الناس راجعين لا يلوي أحد على أحد،", 209, 383], ["كلام جفاة أهل مكة عند الهزيمة", "ولما وقعت الهزيمة: تكلم رجال من جفاة أهل مكة بما في أنفسهم من الضغن،", 210, 384], ["قصة شيبة بن عثمان الحجبي يوم حنين", "فلما اختلط الناس، اقتحم رسول الله صلى الله عليه وسلم عن بغلته وأصلت السيف، فدنوت أريد ما أريد،", 210, 385], ["نداء العباس أصحاب السمرة ورجوع الناس", "فناديت: يا أصحاب السمرة، يا أصحاب سورة البقرة.", 211, 386], ["رمي النبي ﷺ بالحصيات وانهزام المشركين", "وفي صحيح مسلم: ثم أخذ رسول الله صلى الله عليه وسلم حصيات.", 211, 387], ["وقعة أوطاس ومقتل أبي عامر الأشعري", "وبعث رسول الله صلى الله عليه وسلم في أثر من توجه نحو أوطاس أبا عامر الأشعري، فأدرك بعضهم فناوشوه القتال، فهزمهم الله تعالى. وقتل أبو عامر. فأخذ الراية أبو موسى الأشعري.", 212, 388], ["جمع سبي حنين وغنائمها", "وأمر رسول الله صلى الله عليه وسلم بالسبي والغنائم أن يجمع.", 212, 389], ["قسم الغنائم وإعطاء المؤلفة قلوبهم", "ثم بدأ بالأموال فقسمها: وأعطى المؤلفة قلوبهم أول الناس فأعطى أبا سفيان مائة من الإبل.", 212, 390], ["موجدة الأنصار وخطبته ﷺ فيهم", "وجدت الأنصار في أنفسهم. حتى كثرت منهم القالة، حتى قال قائلهم: لقي والله رسول الله قومه.", 213, 391], ["قدوم الشيماء بنت الحارث وإسلامها", "وقدمت الشيماء بنت الحارث - أخت رسول الله صلى الله عليه وسلم من الرضاعة -", 214, 392], ["المن على سبي هوازن", "وقدم وفد هوازن على رسول الله صلى الله عليه وسلم، وهم أربعة عشر رجلا.", 214, 393], ["غزوة الطائف", "ولما أراد المسير إلى الطائف - وكانت في شوال سنة ثمان -", 216, 394], ["بعث الطفيل بن عمرو لهدم ذي الكفين", "بعث الطفيل بن عمرو إلى ذي الكفين - صنم عمرو بن حممة الدوسي - يهدمه، وأمره أن يستمد قومه ويوافيه بالطائف", 216, 395], ["موافاة الطفيل وقومه النبي ﷺ بالطائف", "وانحدر معه من قومه أربعمائة سراعا. فوافوا النبي صلى الله عليه وسلم بالطائف - بعد مقدمه بأربعة أيام - وقدم بدبابة ومنجنيق.", 217, 396], ["حصار الطائف ونصب المنجنيق", "فحاصرهم ثمانية عشر يوما. ونصب عليهم المنجنيق - وهو أول من رمى به في الإسلام -", 217, 397], ["عتق من نزل من حصن الطائف من العبيد", "فخرج منهم بضعة عشر رجلا، فيهم أبو بكرة بن مسروج، فأعتقهم رسول الله صلى الله عليه وسلم،", 217, 398], ["الرحيل عن الطائف", "ولم يؤذن في فتح الطائف. فأمر رسول الله صلى الله عليه وسلم عمر بن الخطاب رضي الله عنه، فأذن بالرحيل،", 217, 399], ["عمرة الجعرانة والرجوع إلى المدينة", "ثم خرج إلى الجعرانة. فدخل منها إلى مكة محرما بعمرة فقضاها. ثم رجع إلى المدينة.", 218, 400], ["قدوم النبي ﷺ المدينة من تبوك", "قال ابن إسحاق: وقدم رسول الله صلى الله عليه وسلم المدينة من تبوك في رمضان.", 219, 401], ["وفد ثقيف", "وقدم عليه في ذلك الشهر وفد ثقيف.", 219, 402], ["إسلام عروة بن مسعود ومقتله في قومه", "اتبع أثره عروة بن مسعود، حتى أدركه قبل أن يدخل المدينة. فأسلم،", 219, 403], ["ائتمار ثقيف على الإرسال إلى رسول الله ﷺ", "ثم أقامت ثقيف بعد قتل عروة شهرا. ثم ائتمروا بينهم.", 219, 404], ["قدوم عبد ياليل ومن معه وتأمير عثمان بن أبي العاص", "فلما أسلموا أمر عليهم عثمان بن أبي العاص - وكان من أحدثهم سنا -", 220, 405], ["هدم اللات", "فلما توجهوا راجعين بعث معهم أبا سفيان والمغيرة بن شعبة، حتى إذا قدموا الطائف أراد المغيرة: أن يقدم أبا سفيان، فأبى،", 220, 406], ["بعث المصدقين لأخذ الصدقات", "ولما قدم رسول الله صلى الله عليه وسلم المدينة، ودخلت سنة تسع، بعث المصدقين يأخذون الصدقات من الأعراب.", 223, 408], ["بعث علي لهدم صنم طيء وهروب عدي إلى الشام", "وفيها: بعث عليا رضي الله عنه إلى صنم طي ليهدمه. فشنوا الغارة على محلة آل حاتم مع الفجر. فهدموه.", 223, 409], ["المن على ابنة حاتم", "قالت: فمن علي، وسألته الحملان، فأمر لها به وكساها وحملها وأعطاها نفقة.", 224, 410], ["قدوم عدي بن حاتم وإسلامه", "قال: فأتيته، وهو جالس في المسجد. فقال القوم: هذا عدي بن حاتم", 224, 411], ["قصة كعب بن زهير", "قال ابن إسحاق: لما قدم رسول الله صلى الله عليه وسلم من الطائف كتب بجير بن زهير إلى أخيه كعب:", 225, 412], ["قدوم كعب بن زهير وإسلامه", "ثم خرج حتى قدم المدينة. فنزل على رجل كان بينه وبينه معرفة. فغدا به إلى رسول الله صلى الله عليه وسلم.", 227, 413], ["غزوة تبوك", "قال ابن إسحاق: كانت في زمان عسرة من الناس، وجدب من البلاد، حين طابت الثمار، فالناس يحبون المقام في ثمارهم وظلالهم.", 230, 414], ["استئذان الجد بن قيس في التخلف", "فقال ذات يوم - وهو في جهازه - للجد بن قيس هل لك في جلاد بني الأصفر؟ \" فقال: يا رسول الله، أوتأذن لي ولا تفتني؛", 230, 415], ["نفقة عثمان في جيش العسرة", "وأنفق عثمان ثلاثمائة بعير بأحلاسها، وأقتابها وعدتها، وألف دينار عينا.", 230, 416], ["مجيء البكائين", "وجاء البكاءون - وهم سبعة - يستحملون رسول الله صلى الله عليه وسلم.", 231, 417], ["تصدق علبة بن يزيد بعرضه", "وقام علبة بن يزيد، فصلى من الليل وبكى.", 231, 418], ["الخروج إلى تبوك وتخلف المنافقين ونفر من المسلمين", "واستخلف على المدينة محمد بن مسلمة الأنصاري. فلما سار رسول الله صلى الله عليه وسلم، تخلف عبد الله بن أبي ومن كان معه، وتخلف نفر من المسلمين من غير شك ولا ارتياب،", 231, 419], ["تخليف علي على أهله ولحاقه بالجرف", "ولما خرج رسول الله صلى الله عليه وسلم خلف عليا على أهله. فقال المنافقون: ما خلفه إلا استثقالا له، وتخففا منه، فأخذ سلاحه ولحق به بالجرف،", 231, 420], ["لحاق أبي خيثمة برسول الله ﷺ", "ثم قدم ناضحه فارتحله، ثم خرج حتى أدرك رسول الله صلى الله عليه وسلم حين نزل تبوك.", 232, 421], ["المرور بالحجر من ديار ثمود", "وقد كان رسول الله صلى الله عليه وسلم، لما مر بالحجر - من ديار ثمود - قال: لا تدخلوا على هؤلاء القوم المعذبين، إلا أن تكونوا", 232, 422], ["الريح الشديدة بتبوك", "فهبت ريح شديدة، فقام رجل. فحملته الريح حتى ألقته بجبلي طيء.", 233, 423], ["نزول المطر بالدعاء", "وأصبح الناس ولا ماء معهم. فشكوا ذلك إلى رسول الله صلى الله عليه وسلم، فدعا الله. فأرسل الله سحابة. فأمطرت حتى ارتوى الناس واحتملوا حاجتهم من الماء.", 233, 424], ["لحاق أبي ذر ماشيا", "وتلوم على أبي ذر بعيره. فلما أبطأ عليه أخذ متاعه على ظهره، ثم خرج يتبع أثر رسول الله صلى الله عليه وسلم ماشيا.", 233, 425], ["وفاة أبي ذر بفلاة من الأرض", "فكفنه الأنصاري، وأقاموا عليه ودفنوه في نفر كلهم يمان \".", 234, 426], ["مصالحة صاحب أيلة وأهل جربا وأذرح", "ولما انتهى رسول الله صلى الله عليه وسلم إلى تبوك، أتاه صاحب أيلة، فصالحه وأعطاه الجزية، وأتاه أهل جربا وأذرح، فأعطوه الجزية، وكتب لهم كتابا.", 234, 427], ["بعث خالد بن الوليد إلى أكيدر دومة", "ثم بعث خالد بن الوليد إلى أكيدر دومة،", 235, 428], ["الانصراف من تبوك إلى المدينة", "فأقام رسول الله صلى الله عليه وسلم بتبوك بضع عشرة ليلة. ثم انصرف إلى المدينة.", 235, 429], ["موت عبد الله ذي البجادين", "وإذا عبد الله ذو البجادين - والبجاد الكساء الأسود - المزني قد مات، وإذا هم قد حفروا له،", 235, 430], ["مسجد الضرار وهدمه", "وكان أصحاب مسجد الضرار أتوه - وهو يتجهز إلى تبوك -", 235, 431], ["تلقي أهل المدينة لرسول الله ﷺ", "ولما دنا رسول الله صلى الله عليه وسلم من المدينة، خرج الناس لتلقيه، والنساء والصبيان والولائد يقلن:", 236, 432], ["قصة الثلاثة الذين خلفوا وتوبتهم", "وفي غزوة تبوك: كانت قصة تخلف كعب بن مالك، ومرارة بن الربيع، وهلال بن أمية الواقفي. ممن شهدوا بدرا.", 237, 433], ["وفود العرب سنة الوفود", "ولما فرغ رسول الله صلى الله عليه وسلم من تبوك، وأسلمت ثقيف. ضربت إليه أكباد الإبل، تحمل وفود العرب من كل وجه، في سنة تسع. وكانت تسمى: سنة الوفود.", 237, 434], ["سرية عيينة بن حصن إلى بني تميم", "جاءوا في أسرى بني تميم، الذين أخذتهم سرية عيينة بن حصن الفزاري في المحرم من هذه السنة.", 238, 435], ["وفد بني تميم", "فقدم عليه عطارد بن حاجب التميمي، في أشراف من بني تميم،", 238, 436], ["إسلام وفد بني تميم", "فلما فرغ القوم أسلموا، وجوزهم رسول الله صلى الله عليه وسلم فأحسن جوائزهم.", 241, 437], ["وفد طيء", "وقدم على رسول الله صلى الله عليه وسلم وفد طيء، فيهم زيد الخيل - وهو سيدهم - فعرض عليهم رسول الله صلى الله عليه وسلم الإسلام فأسلموا وحسن إسلامهم.", 241, 438], ["موت زيد الخيل", "فلما انتهى إلى ماء من مياه نجد - يقال له \" فردة \" - أصابته الحمى بها فمات.", 242, 439], ["وفد عبد القيس", "وقدم على رسول الله صلى الله عليه وسلم، الجارود العبدي في وفد عبد القيس، وكان نصرانيا،", 242, 440], ["إسلام المنذر بن ساوى", "وقد كان رسول الله صلى الله عليه وسلم بعث العلاء بن الحضرمي - قبل فتح مكة - إلى المنذر بن ساوى العبدي، فأسلم وحسن إسلامه.", 242, 441], ["وفد بني حنيفة", "وقدم على رسول الله صلى الله عليه وسلم وفد بني حنيفة، فيهم مسيلمة الكذاب،", 243, 442], ["ردة مسيلمة وادعاؤه النبوة", "ثم انصرفوا فلما انتهوا إلى اليمامة، ارتد عدو الله وتنبأ، وقال: إني أشركت في الأمر معه.", 243, 443], ["كتاب مسيلمة وجواب رسول الله ﷺ", "وكتب لرسول الله صلى الله عليه وسلم: من مسيلمة رسول الله إلى محمد رسول الله،", 243, 444], ["حجة أبي بكر بالناس", "ثم بعث أبا بكر رضي الله عنه أميرا على الحج ليقيم للناس حجهم.", 244, 445], ["نزول براءة وقراءة علي لها يوم النحر", "ثم نزلت سورة براءة في نقض ما بين رسول الله صلى الله عليه وسلم وبين المشركين من العهد الذي كانوا عليه. فأرسل بها علي بن أبي طالب على ناقته العضباء، ليقرأ براءة على الناس.", 244, 446], ["حجة الوداع", "فخرج لها لخمس بقين من ذي القعدة في آخر سنة عشر.", 245, 447], ["خطبته بمنى", "ولما كان بمنى خطب الناس خطبته التي بين فيها ما بين:", 245, 448], ["الرجوع إلى المدينة بعد الحج", "فلما انقضى حجه، رجع إلى المدينة. فأقام صلى الله عليه وسلم بقية ذي الحجة والمحرم وصفر.", 246, 449], ["ابتداء وجع رسول الله ﷺ", "ثم ابتدأ برسول الله صلى الله عليه وسلم وجعه الذي مات فيه في آخر صفر.", 246, 450], ["بعث أسامة بن زيد إلى البلقاء", "فلما كان من الغد دعا أسامة بن زيد. وأمره أن يسير إلى موضع مقتل أبيه زيد بن حارثة، وأن يوطئ الخيل تخوم البلقاء والداروم من أرض فلسطين.", 246, 451], ["خطبته في إنفاذ بعث أسامة", "فصعد المنبر \" فحمد الله وأثنى عليه، ثم قال: أيها الناس، أنفذوا بعث أسامة،", 246, 452], ["عسكرة أسامة بالجرف", "وخرج أسامة بجيشه، فعسكر بالجرف، وتتام إليه الناس.", 247, 453], ["مرض رسول الله ﷺ", "\" لما ثقل برسول الله صلى الله عليه وسلم، هبطت وهبط الناس معي إلى المدينة، فدخلت على رسول الله صلى الله عليه وسلم، وقد أصمت، فلا يتكلم.", 247, 454], ["استغفاره لأهل البقيع", "قد أمرت أن أستغفر لأهل هذا البقيع، فانطلق معي.", 247, 455], ["تمريضه في بيت عائشة", "فلما استعز به، دعا نساءه فاستأذنهن: أن يمرض في بيت عائشة رضي الله عنها، فأذن له.", 248, 456], ["خطبة تخيير العبد وسد الأبواب إلا باب أبي بكر", "خطب رسول الله صلى الله عليه وسلم، فقال: إن الله خير عبدا بين الدنيا وبين ما عنده، فاختار ذلك العبد ما عند الله. فبكى أبو بكر،", 248, 457], ["آخر صعوده المنبر والوصية بالأنصار", "فصعد المنبر - ولم يصعده بعد ذلك اليوم - فحمد الله، وأثنى عليه، ثم قال: أوصيكم بالأنصار خيرا.", 248, 458], ["أمر أبي بكر بالصلاة بالناس", "اشتد مرض رسول الله صلى الله عليه وسلم، فقال: مروا أبا بكر، فليصل بالناس،", 248, 459], ["وفاة رسول الله ﷺ", "فتوفي رسول الله صلى الله عليه وسلم حين اشتد الضحى من ذلك اليوم.", 249, 460], ["مقالة عمر وخطبة أبي بكر بعد الوفاة", "لما توفي رسول الله صلى الله عليه وسلم قام عمر. فقال: إن رجالا من المنافقين يزعمون أن رسول الله صلى الله عليه وسلم قد توفي،", 249, 461]];
export const KH=[["حديث السقيفة", "فلما قبض رسول الله صلى الله عليه وسلم: انحاز هذا الحي من الأنصار إلى سعد بن عبادة في سقيفة بني ساعدة.", 251, 462], ["خطبة عمر في شأن بيعة أبي بكر", "فغضب عمر، وقال: إني - إن شاء الله - لقائم العشية في الناس، فمحذرهم من هؤلاء الذين يريدون أن يغصبوهم أمرهم،", 251, 463], ["بيعة أبي بكر في السقيفة", "فقلت: ابسط يدك يا أبا بكر. فبسطها، فبايعته. ثم بايعه المهاجرون. ثم بايعه الأنصار.", 255, 464], ["البيعة العامة لأبي بكر", "فبايع الناس أبا بكر البيعة العامة، بعد بيعة السقيفة.", 255, 465], ["خطبة أبي بكر بعد البيعة", "ثم تكلم أبو بكر رضي الله عنه. فحمد الله، وأثنى عليه بالذي هو أهله. ثم قال: \" أما بعد، أيها الناس، فإني قد وليت عليكم. ولست بخيركم،", 255, 466], ["إنفاذ جيش أسامة وهزيمة الروم", "فلما نزل بذي خشب قبض رسول الله، وارتدت العرب.", 256, 467], ["ردة العرب وعزم أبي بكر على قتالهم", "\" لما توفي رسول الله صلى الله عليه وسلم، وكان أبو بكر، وكفر من كفر من العرب، قال عمر لأبي بكر: كيف تقاتل الناس،", 257, 468], ["قدوم عيينة والأقرع على أبي بكر", "وقدم على أبي بكر عيينة بن حصن، والأقرع بن حابس في رجال من أشراف العرب.", 258, 469], ["تجهز أبي بكر للمسير إلى أهل الردة", "فأمر أبو بكر رضي الله عنه الناس بالتجهز، وأجمع على المسير بنفسه.", 259, 470], ["بعث المصدقين في العرب", "وقد كان رسول الله صلى الله عليه وسلم - لما صدر من الحج سنة عشر - وقدم المدينة: أقام حتى رأى هلال المحرم سنة إحدى عشرة. فبعث المصدقين في العرب.", 259, 471], ["ثبات عدي بن حاتم وطيء على الإسلام", "فلما رأوا منه الجد كفوا عنه. وأسلموا له.", 260, 472], ["عدي بن حاتم وعمر", "فلما كان زمن عمر رأى من عمر جفوة.", 261, 473], ["خروج أبي بكر لقتال أهل الردة", "فخرج في مائة من المهاجرين والأنصار، وخالد يحمل اللواء حتى نزل بقعاء، يريد أن يتلاحق الناس ويكون أسرع لخروجهم.", 261, 474], ["تأمير خالد على الناس", "فدعا خالدا فأمره على الناس وكتب معه هذا الكتاب.", 261, 475], ["كتاب أبي بكر لأمرائه", "ويروى أن أبا بكر كتب مع هذا كتابا آخر وأمر خالدا أن يقرأه في كل مجمع، وهو:", 262, 476], ["مسير خالد إلى بزاخة", "لما سار خالد إلى بزاخة كان عدي بن حاتم معه، وقد انضم إليه من طيء ألف،", 265, 477], ["إسلام جديلة على يد عدي", "فجاءهم عدي. فدعاهم إلى الإسلام فأسلموا.", 265, 478], ["دعوة خالد طليحة وإباؤه", "فلما انتهوا إلى طليحة الأسدي وجدوه وقد ضربت له قبة وأصحابه حوله.", 266, 479], ["وقعة بزاخة", "فلما كان من السحر نهض خالد. فعبأ أصحابه ووضع ألويته مواضعها. ودفع اللواء الأعظم إلى زيد بن الخطاب.", 266, 480], ["قتل حبال بن أبي حبال", "وأسر حبال بن أبي حبال فأرادوا أن يبعثوا به إلى أبي بكر. فقال اضربوا عنقي، ولا تروني محمديكم هذا، فضربوا عنقه.", 267, 481], ["انصراف فزارة عن طليحة", "يا بني فزارة هكذا - وأشار تحت الشمس - انصرفوا. هذا والله كذاب.", 267, 482], ["أسر عيينة بن حصن", "فانصرفت فزارة وذهب عيينة وأخوه في آثارهما. فأدرك عيينة فأسر. وأفلت أخوه.", 268, 483], ["هرب طليحة إلى الشام", "فوثب على فرسه وحمل امرأته وراءه. ثم ولى هاربا. وقال: من استطاع منكم أن يفعل هكذا فليفعل ثم هرب حتى قدم الشام.", 268, 484], ["قتل طليحة عكاشة وثابت بن أقرم", "فلما أدبر ناداه عكاشة بن محصن يا طليحة، فعطف عليه فقتل عكاشة ثم أدركه ثابت فقتله أيضا طليحة،", 268, 485], ["تأمين خالد بني أسد", "فنادى خالد: من قام فهو آمن. فقام الناس كلهم.", 269, 486], ["إعلان بني عامر الإسلام", "وسمعت بذلك بنو عامر. فأعلنوا الإسلام.", 269, 487], ["تحريق الأسرى في الحظائر", "وأمر خالد بالحظائر أن تبنى، ثم أوقد فيها النار. ثم أمر بالأسرى فألقيت فيها.", 269, 488], ["أخذ أم طليحة", "وأخذت أم طليحة فعرض عليها الإسلام، فوثبت.", 269, 489], ["رجوع بني عامر وغيرهم إلى الإسلام", "ولما أوقع الله ببني أسد وفزارة ما أوقع ببزاخة بث خالد السرايا، ليصيبوا من قدروا عليه ممن هو على ردته.", 269, 490], ["تأمين عامر وغطفان عند أجا وسلمى", "ثم عمد خالد إلى جبلي طيء - أجا وسلمى - فأتته عامر وغطفان يدخلون الإسلام ويسألونه الأمان على مياههم وبلادهم.", 270, 491], ["بعث عيينة موثقا إلى أبي بكر", "وبعث بعيينة إلى أبي بكر مجموعة يداه في وثاقه", 270, 492], ["وفد أسد وغطفان على أبي بكر", "قدمت مع أسد وغطفان على أبي بكر وافدا، حين فرغ خالد منهم.", 270, 493], ["رد عمر الحلقة والكراع إلى أهلها", "فلما توفي رأى عمر أن الإسلام قد ضرب بجرانه. فدفعه إلى أهله وإلى ورثة من مات منهم.", 271, 494], ["مسير خالد إلى اليمامة", "فلما فرغ خالد من بزاخة وبني عامر أظهر أن أبا بكر عهد إليه أن يسير إلى أرض بني تميم، وإلى اليمامة،", 271, 495], ["لحاق الأنصار بخالد", "فابعثوا إلى خالد يقيم حتى تلحقوا. فبعثوا إليه فأقام حتى لحقوه.", 272, 496], ["منع مالك بن نويرة الصدقة", "فلما بلغته وفاة النبي صلى الله عليه وسلم جفل إبل الصدقة - أي ردها إلى أهلها فلذلك سمي الجفول -", 272, 497], ["أخذ السرية قوم مالك بن نويرة", "فلما وصلتهم السرية - مع طلوع الشمس - فزعوا إلى السلاح.", 273, 498], ["قتل مالك بن نويرة وقومه", "فأمر بهم خالد فقتلوا، وأمر برأس مالك فجعل أثفية للقدر ورثاه أخوه متمم بقصائد كثيرة.", 274, 499], ["وفد بني حنيفة ومعهم مسيلمة", "قدمت على النبي صلى الله عليه وسلم وفود العرب، فلم يقدم علينا وفد أقسى قلوبا، ولا أحرى أن لا يكون الإسلام يقر في قلوبهم - من بني حنيفة وكان مسيلمة مع الوفد", 274, 500], ["دعوى مسيلمة الشركة في النبوة وكتابه", "فلما انصرفوا إلى اليمامة ادعى أن النبي صلى الله عليه وسلم أشركه في النبوة،", 274, 501], ["ردة أهل اليمامة مع مسيلمة", "وجد بعدو الله ضلاله بعد وفاة رسول الله صلى الله عليه وسلم. وأصفقت معه بنو حنيفة على ذلك، إلا أفذاذا من ذوي عقولهم.", 274, 502], ["شهادة الرجال بن عنفوة لمسيلمة", "وكان من أعظم ما فتن به قومه شهادة الرجال بن عنفوة له بإشراك النبي صلى الله عليه وسلم إياه في الأمر.", 274, 503], ["لحاق ابن عمر اليشكري بخالد", "فبلغ ذلك مسيلمة ومحكم وأشرافهم فطلبوه ففاتهم. ولحق بخالد. فأخبره بحالهم. ودله على عوراتهم.", 275, 504], ["بئر بني حنيفة وبصاق مسيلمة", "وحفرت بنو حنيفة بئرا فاستعذبوها، فأتوا مسيلمة. وطلبوا أن يبارك فيها، فبصق فيها فعادت ملحا أجاجا.", 276, 505], ["قدوم بعض أسد وغطفان على أبي بكر يطلبون البيعة", "فلما أظفر الله خالدا بهم تسلل بعضهم إلى المدينة، يسألون أبا بكر أن يبايعهم على الإسلام.", 276, 506], ["كتاب أبي بكر إلى خالد مع شريك الفزاري", "ثم رزقني الله الإنابة فجئت أبا بكر. فأمرني بالمسير إلى خالد. وكتب معي إليه.", 277, 507], ["حيرة أهل اليمامة بمسير خالد", "ولما اتصل بأهل اليمامة مسير خالد إليهم بعد الذي صنع بأمثالهم، حيرهم ذلك. وجزع له محكم بن طفيل سيدهم.", 277, 508], ["إنذار عمير بن ضابئ أهل اليمامة", "فقال له خالد: تقدم إلى قومك فاكسرهم.", 278, 509], ["خطبة ثمامة بن أثال في بني حنيفة", "وقام ثمامة بن أثال فيهم. فقال: \" اسمعوا مني وأطيعوا أمري، ترشدوا.", 279, 510], ["تقديم خالد الطلائع من البطاح", "لما سار خالد من البطاح، وجاء أرض بني تميم قدم مائتي فارس عليهم معن بن عدي.", 280, 511], ["أسر مجاعة بن مرارة وقتل أصحابه", "فانطلقوا. وأخذوا مجاعة بن مرارة في ثلاثة وعشرين رجلا من قومه خرجوا في طلب رجل أصاب فيهم دما، وهم لا يشعرون بإقبال خالد.", 280, 512], ["حبس مجاعة عند أم متمم", "ودفعه إلى أم متمم زوجته. وأمرها أن تحسن إساره.", 281, 513], ["نزول خالد عقرباء", "فأجمعوا أن ينتهي إلى عقرباء. فزحف خالد بالمسلمين إليها.", 282, 514], ["وقعة اليمامة", "فلما فرغ خالد من ضرب عسكره - وبنو حنيفة تسوي صفوفها - نهض خالد إلى صفوفه فصفها.", 283, 515], ["مقتل زيد بن الخطاب", "وجعل يشتد بالراية في نحور العدو. ثم ضارب بسيفه حتى قتل.", 283, 516], ["مقتل سالم مولى أبي حذيفة وأبي حذيفة", "ولقد كان الناس يتفرقون في كل وجه وإن سالما وثابتا لقائمان حتى قتل سالم وقتل أبو حذيفة مولاه.", 284, 517], ["مقتل محكم بن الطفيل ودخول الحديقة", "فلم تكن لهم ناهية حتى انتهوا إلى محكم بن الطفيل فقتلوه. ثم انتهوا إلى الحديقة فدخلوها، فقاتلوا أشد القتال حتى اختلطوا فيها.", 284, 518], ["حملة عباد بن بشر وفتح الحديقة", "فخرج أمامهم حتى ساقوا بني حنيفة منهزمين، حتى انتهوا إلى الحديقة فأغلق عليهم. ثم إن الله فتح الحديقة فاقتحم عليهم المسلمون.", 285, 519], ["انقطاع الحرب بعد العصر", "دخلنا الحديقة حين جاء وقت الظهر واستحر القتل، فأمر خالد المؤذن فأذن على جدار الحديقة بالظهر. والقوم مقبلون على القتل حتى انقطعت الحرب بعد العصر.", 285, 520], ["الوقوف على مسيلمة قتيلا", "إن الذي تبتغون لرجل أصيفر أخينس. فوجدوه، فوقف عليه خالد. فحمد الله كثيرا، وأمر به فألقي في البئر التي كان يشرب منها.", 286, 521], ["صلح خالد مع بني حنيفة بخدعة مجاعة", "فقال مجاعة: إني لك ناصح. وإن السيف قد أفناك. فتعال أصالحك عن قومي.", 286, 522], ["تمام الصلح وكتاب أبي بكر يقطر الدم", "فبينا هم على ذلك إذ جاء كتاب أبي بكر يقطر الدم وفيه \" إن أظفرك الله بهم فلا تستبق رجلا مرت عليه الموسى \".", 287, 523], ["تاريخ وقعة اليمامة وقتلى بني حنيفة", "وكانت وقعة اليمامة في ربيع الأول سنة اثنتي عشرة.", 288, 524], ["ردة بني سليم وانتهاب اللطيمة", "فخرجت بها الرسل حتى إذا كانت بأرض بني سليم بلغتهم وفاة النبي صلى الله عليه وسلم. فتشجع بعض بني سليم على أخذها والردة", 288, 525], ["استعمال معن بن حاجر على مسلمي بني سليم", "فلما ولي أبو بكر رضي الله عنه كتب إلى معن بن حاجر فاستعمله على من أسلم من بني سليم.", 289, 526], ["لحاق معن بخالد واستخلاف طريفة", "فلما بدا لأبي بكر أن يوجه خالدا، كتب إلى معن أن يلحق بخالد، ويستعمل على عمله أخاه طريفة بن حاجر ففعل.", 289, 527], ["قتل الفجاءة وتحريقه", "إذ قدم الفجاءة - واسمه إياس بن عبد الله بن عبد ياليل - على أبي بكر.", 289, 528], ["أسر الفجاءة وتحريقه بالنار", "فبعث به في جامعته مع عشرة من بني سليم. فأرسل به أبو بكر إلى بني جشم فحرقته بالنار.", 290, 529], ["مقتل قبيصة على يد حميضة", "وقدم على أبي بكر - رضي الله عنه - قبيصة - أحد بني الظربان - فذكر أنه مسلم.", 290, 530], ["كتاب أبي بكر إلى خالد في بني سليم", "وكتب أبو بكر رضي الله عنه إلى خالد: \" إن أظفرك الله ببني حنيفة فأقل اللبث فيهم، حتى تنحدر إلى بني سليم،", 291, 531], ["قتال خالد بني سليم", "وكان الذي جمعهم أبو شجرة بن عبد العزى فانتهى خالد إلى جمعهم مع الصبح.", 291, 532], ["إسلام أبي شجرة", "ثم أسلم، وجعل يعتذر.", 291, 533], ["قدوم أبي شجرة على عمر", "فلما كان زمن عمر رضي الله عنه قدم المدينة، وأناخ راحلته بصعيد بني قريظة ثم أتى عمر", 291, 534], ["ردة أهل البحرين", "لما ارتدت العرب - بعد وفاة رسول الله صلى الله عليه وسلم - قال كسرى: من يكفيني أمر العرب؟", 292, 535], ["أخذ كسرى ستمائة من بكر بن وائل", "فأرسل إليهم. وأخذ منهم ستمائة الأشرف فالأشرف.", 292, 536], ["ردة أهل هجر وثبات عبد القيس بالجارود", "وارتد أهل هجر عن الإسلام. فقام الجارود بن المعلى في قومه فقال:", 292, 537], ["خروج أبان بن سعيد من البحرين", "فأبى. وانطلق في ثلاثمائة رجل يبلغونه المدينة.", 293, 538], ["بعث العلاء بن الحضرمي إلى البحرين", "فدعا أبو بكر العلاء بن الحضرمي. فبعثه إلى البحرين في ستة عشر راكبا، وقال امض فإن أمامك عبد القيس فسار.", 293, 539], ["قتال العلاء بكر بن وائل بالمشقر", "فنزل العلاء بحصن يقال له جواثي، وكان مخارق قد نزل بمن معه من بكر ابن وائل حصن المشقر - حصن عظيم لعبد القيس - فسار إليهم", 293, 540], ["حصار العلاء بجواثي", "وسار الحطم وأبجر العجلي حتى حصروا العلاء بجواثي.", 294, 541], ["تبييت المسلمين عسكر الحطم", "فمكثوا على ذلك محصورين فسمع العلاء وأصحابه ذات ليلة لغطا في العسكر", 294, 542], ["مقتل الحطم وأبجر العجلي", "قال: أنا أحملك، فلما دنا منه قتله. وقطعت رجل أبجر العجلي. فمات منها.", 295, 543], ["قتال دارين وصلح أهلها", "ثم سار العلاء إلى مدينة دارين فقاتلهم قتالا شديدا، وضيق عليهم.", 295, 544], ["العلاء يخوض البحر إلى دارين", "ثم سار العلاء إلى الخط، حتى نزل إلى الساحل فجاءه نصراني فقال ما لي إن دللتك على مخاضة تخوض منها الخيل إلى دارين؟", 296, 545], ["صلح أهل الردة من البحرين", "ولما رأى ذلك أهل الردة من أهل البحرين، صالحوا على ما صالح عليه أهل هجر.", 296, 546], ["وفد عبد القيس إلى أبي بكر", "ولما ظهر العلاء على أهل الردة والمجوس: بعث رجالا من عبد القيس إلى أبي بكر رضي الله عنه. فنزلوا على طلحة والزبير رضي الله عنهما.", 296, 547], ["عمر يمحو كتاب الإقطاع", "فانطلقوا بالكتاب إلى عمر رضي الله عنه. فلما قرأه: تفل في الكتاب ومحاه.", 297, 548], ["ردة أهل دبا وأزد عمان", "فلما توفي رسول الله صلى الله عليه وسلم منعوا الصدقة وارتدوا. فدعاهم حذيفة إلى التوبة. فأبوا.", 298, 549], ["مسير عكرمة إلى أهل دبا", "فسار عكرمة في نحو ألفين من المسلمين.", 298, 550], ["هزيمة أهل دبا وحصارهم", "فانهزم العدو حتى دخلوا مدينة دبا. فحصرهم المسلمون شهرا.", 299, 551], ["نزول أهل دبا على حكم حذيفة", "فأرسلوا إلى حذيفة. يسألونه الصلح. فقال: لا، إلا بين حرب مجلية أو سلم مخزية.", 299, 552], ["قدوم حذيفة بسبي دبا المدينة", "وقدم حذيفة بسبيهم المدينة. وهم ثلاثمائة من المقاتلة وأربعمائة من الذرية والنساء.", 300, 553], ["عمر يطلق سبي دبا", "فلم يزالوا موقوفين في دار رملة حتى مات أبو بكر. فدعاهم عمر، فقال: انطلقوا إلى أي بلاد شئتم. فأنتم قوم أحرار.", 300, 554], ["مسير خالد إلى العراق", "كتب إلى خالد: \" إذا فرغت من اليمامة فسر إلى العراق، فقد وليتك حرب فارس \".", 301, 556], ["هزيمة الفرس وصلحهم مع خالد", "فالتقى مع خالد فهزم الله المشركين من الفرس.", 301, 557], ["حج أبي بكر بالناس", "وفيها حج أبو بكر رضي الله عنه بالناس ثم رجع إلى المدينة.", 301, 558], ["بعث الجنود إلى الشام", "فبعث أبو بكر رضي الله عنه الجنود إلى الشام. وأمر عليهم يزيد بن أبي سفيان وأبا عبيدة عامر بن الجراح، وشرحبيل بن حسنة وعمرو بن العاص.", 301, 560], ["أمر خالد بإمداد أهل الشام", "فأمر خالدا - وهو بالحيرة - أن يمد أهل الشام بمن معه من أهل القوة ويستخلف على ضعفة الناس رجلا منهم.", 301, 561], ["فتح بصرى", "وسار حتى وصل إلى الشام، ففتحوا بصرى. وهي أول مدينة فتحت.", 302, 562], ["وقعة أجنادين", "ثم اجتمع المشركون من الروم، فانحاز المسلمون إلى أجنادين، فكانت الوقعة المشهورة وكان النصر للمسلمين.", 302, 563], ["موت الصديق رضي الله عنه", "وفي هذه السنة مات الصديق، ليلة الثلاثاء لسبع عشرة ليلة مضت من جمادى الآخرة.", 302, 564], ["استخلاف عمر بن الخطاب", "واستخلف على الناس عمر بن الخطاب.", 302, 565], ["بيعة أمراء الأجناد لعمر", "ولما ورد كتاب أبي بكر رضي الله عنه إلى أمراء الأجناد باستخلاف عمر بايعوه.", 303, 566], ["وقعة فحل", "ثم ساروا إلى \" فحل \" بناحية الأردن. وقد اجتمع بها الروم. فكانت وقعة \" فحل \" المشهورة ونصر الله المسلمين.", 303, 567], ["المسير إلى دمشق وعزل خالد", "وفيها: ساروا إلى دمشق وعليهم خالد. فأتى كتاب عمر رضي الله عنه بعزل خالد وتأمير أبي عبيدة بن الجراح.", 303, 569], ["أمر عمر بصلاة التراويح جماعة", "وفيها: أمر عمر بصلاة التراويح جماعة", 303, 570], ["مسير جرير بن عبد الله إلى العراق", "وقدم جرير بن عبد الله في ركب من بجيلة، فأشار عليه عمر بالخروج إلى العراق، فسار بهم جرير إلى العراق.", 303, 571], ["وقعة البويب", "ثم اجتمعا. فكانت وقعة البويب المشهورة.", 303, 572], ["تأمير سعد بن أبي وقاص على العراق", "ثم إن عمر أمر سعد بن أبي وقاص رضي الله عنه على العراق، وكتب له وأوصاه", 303, 573], ["نزول سعد بشراف", "فسار سعد بمن معه. فنزل بشراف واجتمع إليه الناس.", 304, 574], ["فتح القادسية", "فكانت وقعة القادسية المشهورة التي نصر الله فيها المسلمين. وهزم المشركين.", 304, 576], ["نزول الكوفة", "فبعث سعد عثمان بن حنيف فارتاد لهم موضع الكوفة اليوم فنزلها", 304, 577], ["تمصير البصرة", "فبعث إليها عتبة بن غزوان في ثلاثمائة رجل حتى نزلها. وهو الذي بصر البصرة.", 305, 578], ["وقعة اليرموك", "وفي هذه السنة كانت وقعة اليرموك المشهورة بالشام.", 305, 579], ["صلح نصارى بيت المقدس", "وخرج عمر إلى الشام، ونزل الجابية. فصالح نصارى بيت المقدس", 305, 580], ["وضع الديوان", "فلما رجع إلى المدينة وضع الديوان. فأعطى العطايا على مقدار السابقة.", 305, 581], ["كتابة التاريخ من الهجرة", "فيها كتب عمر التاريخ. واستشار الصحابة في مبدئه.", 305, 583], ["فتوح كثيرة شرقا وغربا", "فكان فيها فتوح كثيرة شرقا وغربا.", 305, 585], ["فتح تستر", "وفيها فتحت تستر، التي وجد فيها جسد دانيال عليه السلام.", 306, 586], ["زواج عمر أم كلثوم بنت علي", "وفيها: تزوج عمر أم كلثوم بنت علي بن أبي طالب رضي الله عنهم طلبا لصهر رسول الله صلى الله عليه وسلم.", 306, 587], ["عام الرمادة", "فيها: أصاب الناس مجاعة شديدة. وتسمى عام الرمادة لكثرة ما هلك فيها من الناس والبهائم جوعا.", 306, 589], ["استسقاء عمر بالعباس", "فاستسقى عمر بالناس. وسأل العباس أن يدعو الله ويؤمن عمر والناس على دعائه. فأزال الله القحط.", 306, 590], ["طاعون عمواس", "وفيها وقع طاعون عمواس بالشام وقد هلك فيه خمسة وعشرون ألفا.", 306, 591], ["تأمير معاوية على الشام", "فلما بلغ عمر موتهم أمر على الشام معاوية بن أبي سفيان.", 306, 592], ["فتوح كثيرة شرقا وغربا", "فتح فيها فتوح كثيرة شرقا وغربا.", 306, 594], ["فتح مصر والإسكندرية", "وفيها: فتحت مصر والإسكندرية.", 307, 596], ["إجلاء اليهود من الحجاز", "وفيها: أجلى عمر رضي الله عنه اليهود من الحجاز إلى أذرعات وغيرها.", 307, 597], ["فتح نهاوند", "وفيها كان فتح نهاوند وأميرها النعمان بن مقرن، وقتل يومئذ.", 307, 599], ["موت خالد بن الوليد بحمص", "وفيها: مات خالد بن الوليد رضي الله عنه بحمص.", 307, 600], ["مقتل عمرو بن معدي كرب وطليحة بنهاوند", "وفيها: مات عمرو بن معدي كرب، وطليحة بن خويلد الأسدي", 307, 601], ["دخول الأحنف خراسان وهزيمة يزدجرد", "وفيها: دخل الأحنف بن قيس خراسان، وحارب يزدجرد آخر ملوك الفرس. فهزمه الله فيها.", 307, 603], ["اعتمار عمر", "وفيها: اعتمر عمر. فتلقاه نافع بن الحارث - وكان عامله على مكة -", 307, 604], ["مقتل عمر رضي الله عنه", "وفيها: قتل عمر رضي الله عنه. في صلاة الصبح من يوم الأربعاء لأربع ليال بقين من ذي الحجة.", 308, 606], ["استخلاف عثمان بن عفان", "فاستخلف فيها عثمان بن عفان رضي الله عنه. لغرة هلال المحرم - أو لثلاث من المحرم - بعد دفن عمر بثلاثة أيام.", 309, 608], ["وفيات", "وفي هذه السنة توفي سراقة بن مالك، وأم الفضل زوجة العباس وأم أيمن بركة مولاة رسول الله صلى الله عليه وسلم.", 310, 609], ["وفيات", "فتوفي فيها عبد الله بن أم مكتوم المؤذن، وعمير بن وهب بن خلف الجمحي الذي حزر المسلمين يوم بدر.", 310, 611], ["غزو عبد الله بن سعد إفريقية", "وفيها غزا عبد الله بن سعد بن أبي سرح إفريقية ومعه العبادلة", 310, 613], ["موت خارجة بن زيد الأنصاري", "وفيها: مات خارجة بن زيد الأنصاري الذي تكلم بعد الموت.", 310, 614], ["تحويل الساحل إلى جدة", "فخرج عثمان إلى جدة فرآها، وحول الساحل إليها.", 311, 615], ["فتح إفريقية والأندلس", "وفيها - على قول ابن جرير - كان فتح إفريقية والأندلس على يد عبد الله بن سعد بن أبي سرح.", 311, 617], ["عزل عمرو بن العاص عن مصر", "وفيها: عزل عثمان رضي الله عنه عمرو بن العاص عن مصر، وولى عليها عبد الله بن سعد بن أبي سرح.", 311, 618], ["موت عبد الله بن كعب بن عمرو", "وفيها: مات عبد الله بن كعب بن عمرو رضي الله عنه. وكان من أهل بدر.", 311, 619], ["غزو معاوية البحر وموت أم حرام", "فيها غزا معاوية بن أبي سفيان البحر ومعه عبادة بن الصامت، وامرأته أم حرام بنت ملحان - أخت أم سليم - فسقطت عن دابة لها فهلكت.", 311, 621], ["غزو قبرس", "وفيها: غزا معاوية قبرس. فصالحه أهلها.", 312, 622], ["توسعة المسجد النبوي والمسجد الحرام", "فيها: شكى الناس إلى عثمان رضي الله عنه ضيق مسجد رسول الله صلى الله عليه وسلم، فأمر بتوسعته", 312, 624], ["موت سليمان بن ربيعة الباهلي", "وفيها: مات سليمان بن ربيعة الباهلي رضي الله عنه.", 312, 625], ["سقوط خاتم النبي ﷺ في بئر أريس", "وفيها وقع خاتم رسول الله من يد عثمان بن عفان رضي الله عنه في بئر أريس فنزحت ولم يوجد.", 312, 627], ["غزو سعيد بن العاص خراسان", "وفيها: غزا سعيد بن العاص من الكوفة خراسان، ومعه حذيفة بن اليمان، والحسن، والحسين، وعبد الله بن عمر، وعبد الله بن عمرو بن العاص، وعبد الله بن الزبير رضي الله عنهم.", 312, 628], ["أمر أبي ذر ونزوله الربذة", "فكتب معاوية في شأنه إلى عثمان. فكتب عثمان بإشخاص أبي ذر إلى المدينة", 313, 629], ["زيادة النداء الثالث يوم الجمعة", "وفيها: زاد عثمان النداء الثالث يوم الجمعة على الزوراء حين كثر الناس.", 313, 630], ["موت أبي بن كعب", "وفيها: مات أبي بن كعب: سيد القراء وأحد القراء الأربعة.", 313, 631], ["قتل يزدجرد آخر ملوك الفرس", "وفيها: قتل يزدجرد آخر ملوك الفرس،", 313, 633], ["فتح أرمينية", "وفيها: فتح حبيب بن مسلمة الفهري أرمينية.", 313, 634], ["غزوة الصواري", "وقال الواقدي: كان في هذه السنة غزوة الصواري في البحر.", 313, 635], ["غزو معاوية بلاد الروم", "فيها: غزا معاوية بلاد الروم، حتى بلغ مضيق القسطنطينية.", 314, 637], ["وفيات", "وفيها: مات عبد الرحمن بن عوف وعبد الله بن مسعود، وسلمان الفارسي وأبو ذر الغفاري - جندب بن جنادة - والعباس بن عبد المطلب، وأبو سفيان بن حرب رضي الله عنهم.", 314, 638], ["نفي الطاعنين على عثمان من أهل العراق", "وفيها: ذكر أهل العراق عثمان بالسوء وتكلموا فيه بكلام خبيث في مجلس سعيد بن عامر فكتب في أمرهم إلى عثمان. فكتب يأمره بإجلائهم إلى الشام.", 314, 640], ["موت المقداد بن عمرو", "وفيها: مات المقداد بن عمرو رضي الله عنه.", 314, 641], ["تكاتب المنحرفين عن عثمان", "فيها: تكاتب المنحرفون عن عثمان - وكان جمهورهم من أهل الكوفة - وتواعدوا أن يجتمعوا لمناظرته فيما نقموا عليه.", 315, 643], ["وفيات", "وفيها: توفي أبو طلحة الأنصاري، وعبادة بن الصامت رضي الله عنهما.", 315, 644], ["موت عمار بن ربيعة", "وفيها: مات من الصحابة عمار بن ربيعة أسلم قديما وشهد بدرا رضي الله عنه.", 315, 646], ["خروج أهل مصر على عثمان", "وفيها: كان خروج جماعة من أهل مصر ومن وافقهم على عثمان.", 315, 647], ["مقتل عثمان رضي الله عنه", "كانت البلية الكبرى بمحاصرة عثمان رضي الله عنه واغتياله وهو يتلو كتاب الله تعالى، وكان بيد أولئك المجرمين الخوارج في ذي الحجة من هذه السنة.", 316, 648], ["بيعة علي بن أبي طالب", "فلما رأى ذلك علي خرج فبايعه الناس. ولم يدخل في طاعته معاوية وأهل الشام.", 316, 649], ["خروج عائشة وطلحة والزبير إلى البصرة", "وبلغ الخبر عائشة - وهي حاجة - ومعها طلحة، والزبير. فخرجوا", 316, 651], ["وقعة الجمل", "فكانت وقعة الجمل المشهورة لأن عائشة كانت في هودج. على جمل. وعقر الجمل ذلك اليوم.", 317, 652], ["رد عائشة إلى المدينة", "ثم التقى علي وعائشة. فاعتذر كل منهما للآخر. ثم جهزها إلى المدينة.", 317, 653], ["وفيات", "وفي هذه السنة: مات حذيفة بن اليمان، وأبو رافع مولى رسول الله صلى الله عليه وسلم وقدامة بن مظعون رضي الله عنهم.", 317, 654], ["وقعة صفين", "فسار علي رضي الله عنه والتقى هو وأهل الشام بصفين لسبع", 317, 656], ["رفع المصاحف والتحكيم", "رفع أهل الشام المصاحف على رؤوس الرماح ونادوا \" ندعوكم إلى كتاب الله \" فسر الناس وأنابوا إلى الحكومة.", 318, 657], ["اجتماع الحكمين بأذرح", "فلما حل الموعد في رمضان توافوا بأذرح، بدومة الجندل. فلم يتفق الحكمان على شيء.", 318, 658], ["خروج الخوارج بحروراء", "فلما وصل علي الكوفة خرجت عليه الخوارج ; وكفروه حيث رضي بالتحكيم.", 318, 659], ["مناظرة ابن عباس للخوارج", "فأرسل علي إليهم عبد الله بن عباس فأتاهم.", 318, 660], ["قتال علي للخوارج", "فرجع منهم أربعة آلاف، وخرج عليه باقيهم. فقاتلوه فقتل منهم مقتلة عظيمة.", 320, 661], ["وفيات", "وفي هذه السنة مات خباب بن الأرت، وخزيمة ذو الشهادتين وسفينة مولى رسول الله صلى الله عليه وسلم وعبد الله بن سعد بن أبي السرح رضي الله عنهم.", 320, 662], ["قتل محمد بن أبي بكر", "فيها: قتل محمد بن أبي بكر وأحرق.", 320, 664], ["وفيات", "وفيها: مات سهل بن حنيف، وصهيب الرومي.", 320, 665], ["الصلح بين علي ومعاوية", "وفيها: كتب معاوية إلى علي: \" أما إذا شئت فلك العراق. ولي الشام. ونكف السيف عن هذه الأمة. ولا نهريق دماء المسلمين \" ففعل.", 321, 667], ["مقتل علي رضي الله عنه", "وفيها: قتل علي رضي الله عنه. قتله ابن ملجم - رجل من الخوارج - لما خرج لصلاة الصبح لثلاث عشرة ليلة بقيت من رمضان.", 321, 668], ["بيعة الحسن بن علي", "فبايع الناس ابنه الحسن. فبقي خليفة نحو سبعة أشهر.", 321, 669], ["صلح الحسن ومعاوية", "فصالح معاوية. وترك الأمر له وبايعه على أشياء اشترطها. فأعطاه معاوية إياها وأضعافها.", 321, 670]];
